import{I as e,M as n}from"./vue-vendor-CoJ052tP.js";var t={1:{builtInRevision:3,translationOverride:!0,date:"2026-08-01",category:"AI 工程",categoryEn:"AI Engineering",readTime:16,readTimeEn:16,title:"Vibe Coding 工程化：从自然语言意图到可审计的软件交付",titleEn:"Engineering Vibe Coding: From Natural-Language Intent to Auditable Delivery",excerpt:"Vibe Coding 不是“让模型随便写代码”。本文把 AI 编程拆成上下文、计划、实现、验证与审查五个可追踪阶段，建立适用于真实仓库的质量与安全边界。",excerptEn:"Vibe coding is not permission for a model to improvise unchecked. This article turns AI-assisted development into five traceable stages: context, plan, implementation, verification, and review.",content:'\n      <p><strong>适用范围：</strong>使用代码代理、IDE 助手或对话模型维护真实软件仓库的团队。“Vibe Coding”并不是正式的软件工程标准，本文讨论的是如何把这种交互方式纳入可审计的交付流程。</p>\n      <h2>提示词不是规格，生成结果也不是证据</h2>\n      <p>自然语言可以快速表达意图，却常常省略兼容性、数据迁移、权限、性能和失败恢复。可靠流程必须先让代理读取仓库约束、测试入口和变更边界，再形成可验证计划。任何“看起来合理”的实现都只是候选方案，只有差异检查、测试和运行证据才能支撑合并。</p>\n      <h2>五阶段工作流</h2>\n      <ol><li><strong>Context：</strong>限定目录、版本、架构规则与不可修改区域。</li><li><strong>Plan：</strong>写明用户可观察结果、风险、回滚点和验证方法。</li><li><strong>Implement：</strong>保持小批次变更，避免一次改写整个模块。</li><li><strong>Verify：</strong>运行格式、类型、单元、集成与关键路径测试。</li><li><strong>Review：</strong>检查权限扩大、数据破坏、依赖变更和生成代码的维护成本。</li></ol>\n      <h2>AI 代码审查的正确位置</h2>\n      <p>代理可以发现重复、遗漏和常见缺陷，但不能代替责任人审批。自动审查应作为额外信号，不能绕过分支保护、必需检查或领域专家。仓库级指令应定义安全清单和测试要求，而不是只规定代码风格。</p>\n      <h2>验收指标</h2>\n      <p>记录首轮通过率、人工返工量、缺陷逃逸率、测试覆盖的关键行为以及回滚次数。速度提升如果伴随更高的审查成本或线上事故，就不是生产率提升。</p>\n      <h2>一手资料</h2>\n      <ul><li><a href="https://docs.github.com/en/copilot/how-tos/use-copilot-agents" target="_blank" rel="noopener noreferrer">GitHub Docs：Copilot agents</a></li><li><a href="https://docs.github.com/en/copilot/how-tos/use-copilot-agents/request-a-code-review" target="_blank" rel="noopener noreferrer">GitHub Docs：Copilot code review</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> teams using coding agents, IDE assistants, or chat models in real repositories. “Vibe coding” is not a formal engineering standard; this article explains how to place the interaction inside an auditable delivery process.</p>\n      <h2>A prompt is not a specification</h2><p>Natural language compresses intent but often omits compatibility, migration, authorization, performance, and recovery constraints. A reliable agent first reads repository rules and test entry points, then proposes a verifiable plan. Generated code is a candidate; diffs, tests, and runtime evidence justify a merge.</p>\n      <h2>Five stages</h2><ol><li>Context: define scope, versions, and protected areas.</li><li>Plan: state observable outcomes, risks, rollback points, and checks.</li><li>Implement: make small, reviewable changes.</li><li>Verify: run formatting, typing, unit, integration, and critical-path tests.</li><li>Review: inspect privileges, destructive behavior, dependencies, and maintainability.</li></ol>\n      <h2>Where AI review belongs</h2><p>Agent review is an additional signal, not a substitute for accountable approval. It must not bypass branch protection, required checks, or domain experts.</p>\n      <h2>Primary sources</h2><ul><li><a href="https://docs.github.com/en/copilot/how-tos/use-copilot-agents" target="_blank" rel="noopener noreferrer">GitHub Docs: Copilot agents</a></li><li><a href="https://docs.github.com/en/copilot/how-tos/use-copilot-agents/request-a-code-review" target="_blank" rel="noopener noreferrer">GitHub Docs: Copilot code review</a></li></ul>\n    '},2:{builtInRevision:3,translationOverride:!0,date:"2026-07-28",category:"AI 系统",categoryEn:"AI Systems",readTime:18,readTimeEn:18,title:"AI 浪潮下的软件架构：模型、RAG、Agent 与评测体系",titleEn:"Software Architecture in the AI Wave: Models, RAG, Agents, and Evaluation",excerpt:"从模型能力边界出发，分析 RAG、工具调用与 Agent 工作流的适用场景，并建立覆盖质量、成本、延迟、安全和可追溯性的评测闭环。",excerptEn:"Start from model limits, then decide where RAG, tool use, and agent workflows belong. Build an evaluation loop covering quality, cost, latency, safety, and traceability.",content:'\n      <p><strong>适用范围：</strong>把大语言模型接入搜索、知识库、办公或业务系统的产品。模型版本会快速变化，因此架构应围绕能力接口、证据和评测设计，而不是绑定单一模型名称。</p>\n      <h2>先区分四种能力</h2>\n      <p>基础模型负责生成与推理；RAG 为回答提供外部证据；工具调用执行确定性操作；Agent 则在多步任务中维护计划与状态。它们不是递进式“高级功能”：一个可检索回答不一定需要 Agent，一次转账也绝不能只依赖模型自由生成参数。</p>\n      <h2>RAG 的真正边界</h2>\n      <p>RAG 质量由切分、索引、召回、重排、上下文构造和答案引用共同决定。必须分别评估检索命中与最终回答，否则无法判断失败来自知识缺失、召回错误还是模型没有忠实使用证据。</p>\n      <h2>Agent 的控制面</h2>\n      <p>高风险工具采用最小权限、参数校验、幂等键和人工确认；每一步保留输入、工具结果、模型决策和版本。为循环次数、Token、费用和执行时间设置硬上限，并允许取消和恢复。</p>\n      <h2>评测不是上线前的一张表</h2>\n      <p>建立代表真实任务的黄金集，持续跟踪正确性、引用完整度、工具成功率、P95 延迟、单任务成本和安全拒绝。线上反馈先进入隔离样本库，再由人工确认是否成为回归用例。</p>\n      <h2>一手资料</h2>\n      <ul><li><a href="https://www.nist.gov/itl/ai-risk-management-framework" target="_blank" rel="noopener noreferrer">NIST AI Risk Management Framework</a></li><li><a href="https://arxiv.org/abs/2005.11401" target="_blank" rel="noopener noreferrer">Retrieval-Augmented Generation 原始论文</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> products connecting language models to search, knowledge, office, or business systems. Model releases change quickly, so architecture should center on capability interfaces, evidence, and evaluation rather than one model name.</p>\n      <h2>Separate four capabilities</h2><p>A foundation model generates; RAG supplies external evidence; tools execute deterministic actions; an agent maintains state across multiple steps. They are not a maturity ladder. A grounded answer may not need an agent, while a financial action must never trust freely generated parameters.</p>\n      <h2>RAG boundaries</h2><p>Quality depends on chunking, indexing, retrieval, reranking, context construction, and citation. Measure retrieval and answer quality separately.</p>\n      <h2>Agent control plane</h2><p>Apply least privilege, validation, idempotency, human approval, complete traces, and hard limits for steps, tokens, money, and time.</p>\n      <h2>Primary sources</h2><ul><li><a href="https://www.nist.gov/itl/ai-risk-management-framework" target="_blank" rel="noopener noreferrer">NIST AI Risk Management Framework</a></li><li><a href="https://arxiv.org/abs/2005.11401" target="_blank" rel="noopener noreferrer">Original RAG paper</a></li></ul>\n    '},3:{builtInRevision:3,translationOverride:!0,date:"2026-07-24",category:"Java",categoryEn:"Java",readTime:16,readTimeEn:16,title:"现代 Java 并发：虚拟线程、结构化并发与性能边界",titleEn:"Modern Java Concurrency: Virtual Threads, Structured Concurrency, and Limits",excerpt:"以 Java 25 为稳定基线，解释虚拟线程适合解决什么、结构化并发如何传播失败与取消，以及为什么吞吐提升仍受数据库、连接池和外部服务约束。",excerptEn:"Using Java 25 as the baseline, explain what virtual threads solve, how structured concurrency propagates failure and cancellation, and why databases and downstream services still cap throughput.",content:'\n      <p><strong>适用范围：</strong>Java 25 LTS 服务端应用。虚拟线程是正式能力；结构化并发在该版本仍需按预览能力管理，生产采用前必须核对编译参数与升级策略。</p>\n      <h2>虚拟线程优化等待，不消除资源上限</h2>\n      <p>虚拟线程让“每请求一线程”的阻塞代码以更低线程成本扩展，尤其适合大量网络和数据库等待。它不会让 CPU 密集任务自动变快，也不会扩大数据库连接池、下游限流或内存容量。</p>\n      <pre><code>try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {\n  var future = executor.submit(() -&gt; repository.load(id));\n  return future.get();\n}</code></pre>\n      <h2>结构化并发管理任务生命周期</h2>\n      <p>相关子任务被限制在同一个作用域中：父任务结束前等待子任务，失败时按策略取消同组任务，异常不会悄悄遗留在线程池。它改善的是取消、错误传播与可观测性，而不只是语法。</p>\n      <h2>性能验证</h2>\n      <p>用 JFR、线程转储和端到端压测观察固定并发下的吞吐、P95/P99 延迟、连接等待和内存。避免在线程本地变量中保存大对象，并检查任何会固定载体线程的本地调用或兼容性代码。</p>\n      <h2>一手资料</h2><ul><li><a href="https://docs.oracle.com/en/java/javase/25/core/virtual-threads.html" target="_blank" rel="noopener noreferrer">Oracle Java 25：Virtual Threads</a></li><li><a href="https://docs.oracle.com/en/java/javase/25/core/structured-concurrency.html" target="_blank" rel="noopener noreferrer">Oracle Java 25：Structured Concurrency</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> Java 25 LTS server applications. Virtual threads are permanent; structured concurrency must still be managed as a preview feature in this baseline.</p>\n      <h2>Virtual threads optimize waiting</h2><p>They make thread-per-request code scale with lower thread overhead, particularly for network and database waits. They do not accelerate CPU-bound work or expand connection pools and downstream quotas.</p>\n      <h2>Structured task lifetime</h2><p>Related subtasks live in one scope, are joined before the parent proceeds, and can propagate failure and cancellation as a unit. The benefit is lifecycle, error handling, and observability.</p>\n      <h2>Primary sources</h2><ul><li><a href="https://docs.oracle.com/en/java/javase/25/core/virtual-threads.html" target="_blank" rel="noopener noreferrer">Oracle Java 25: Virtual Threads</a></li><li><a href="https://docs.oracle.com/en/java/javase/25/core/structured-concurrency.html" target="_blank" rel="noopener noreferrer">Oracle Java 25: Structured Concurrency</a></li></ul>\n    '},4:{builtInRevision:3,translationOverride:!0,date:"2026-07-20",category:"数据库",categoryEn:"Database",readTime:18,readTimeEn:18,title:"MySQL 8.4 LTS：MVCC、索引、执行计划与事务诊断",titleEn:"MySQL 8.4 LTS: MVCC, Indexes, Execution Plans, and Transaction Diagnosis",excerpt:"从 InnoDB 的聚簇索引和多版本并发控制出发，建立慢查询、锁等待、死锁与事务边界的诊断顺序，并说明何时索引反而增加成本。",excerptEn:"Start with InnoDB clustered indexes and MVCC, then build a disciplined process for diagnosing slow queries, lock waits, deadlocks, and transaction boundaries.",content:'\n      <p><strong>适用范围：</strong>MySQL 8.4 LTS、InnoDB。所有优化结论必须通过真实数据分布、执行计划和负载验证，不能只根据 SQL 外观判断。</p>\n      <h2>从存储结构理解索引</h2>\n      <p>InnoDB 的主键索引是聚簇索引，叶子节点保存整行；二级索引叶子保存索引列与主键值。宽主键会放大每个二级索引，低选择性索引可能让优化器选择全表扫描。联合索引应围绕过滤、排序和回表成本设计。</p>\n      <h2>MVCC 与锁不是互斥概念</h2>\n      <p>一致性读通过 Read View 与 undo 版本读取快照；当前读和写操作仍需要锁。长事务会延长旧版本存活、增加清理压力，并让复制与备份复杂化。使用 <code>SELECT ... FOR UPDATE</code> 前必须明确被锁定的索引范围。</p>\n      <h2>诊断顺序</h2>\n      <ol><li>用慢查询与 Performance Schema 找到真实高成本语句。</li><li>查看 <code>EXPLAIN ANALYZE</code> 的实际行数、循环次数与耗时。</li><li>核对统计信息、索引选择、临时表与排序。</li><li>检查事务持续时间、锁等待与死锁记录。</li><li>以相同数据规模重放，比较修改前后的 P95 与资源消耗。</li></ol>\n      <h2>一手资料</h2><ul><li><a href="https://dev.mysql.com/doc/refman/8.4/en/innodb-storage-engine.html" target="_blank" rel="noopener noreferrer">MySQL 8.4：InnoDB Storage Engine</a></li><li><a href="https://dev.mysql.com/doc/refman/8.4/en/explain.html" target="_blank" rel="noopener noreferrer">MySQL 8.4：EXPLAIN</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> MySQL 8.4 LTS with InnoDB. Every optimization claim must be tested against real distributions, plans, and workload.</p>\n      <h2>Indexes begin with storage</h2><p>The primary-key B-tree is clustered; secondary leaves contain indexed values plus the primary key. Wide keys amplify every secondary index, while low selectivity can make a scan cheaper.</p>\n      <h2>MVCC still has locks</h2><p>Consistent reads use read views and undo versions; current reads and writes still lock. Long transactions retain old versions and increase purge, replication, and recovery pressure.</p>\n      <h2>Diagnosis</h2><p>Start from slow-query evidence, inspect EXPLAIN ANALYZE, validate statistics and row counts, then inspect transaction duration, waits, and deadlocks. Compare P95 latency and resource use under equivalent data.</p>\n      <h2>Primary sources</h2><ul><li><a href="https://dev.mysql.com/doc/refman/8.4/en/innodb-storage-engine.html" target="_blank" rel="noopener noreferrer">MySQL 8.4: InnoDB</a></li><li><a href="https://dev.mysql.com/doc/refman/8.4/en/explain.html" target="_blank" rel="noopener noreferrer">MySQL 8.4: EXPLAIN</a></li></ul>\n    '},5:{builtInRevision:3,translationOverride:!0,date:"2026-07-16",category:"Spring",categoryEn:"Spring",readTime:17,readTimeEn:17,title:"Spring Boot 4.1 生产级架构：配置、可观测性与故障边界",titleEn:"Production Architecture with Spring Boot 4.1: Configuration, Observability, and Failure Boundaries",excerpt:"围绕 Spring Boot 4.1 的自动配置、外部化配置、Actuator、Micrometer 与容器部署，说明如何让服务可启动、可诊断、可降级并可安全升级。",excerptEn:"Use Spring Boot 4.1 auto-configuration, externalized configuration, Actuator, Micrometer, and containers to build services that are diagnosable, degradable, and safely upgradeable.",content:'\n      <p><strong>适用范围：</strong>Spring Boot 4.1 稳定线。升级前必须检查 Java 基线、Spring Framework 版本、Jakarta 命名空间与第三方 starter 兼容性。</p>\n      <h2>自动配置不是魔法</h2>\n      <p>自动配置根据 classpath、Bean 和属性条件装配组件。生产问题排查应能回答“哪个条件创建了这个 Bean、哪个配置源覆盖了值”。使用配置属性类和校验替代散落的字符串读取，对密钥使用专门的 Secret 管理。</p>\n      <h2>把故障限制在边界内</h2>\n      <p>HTTP 客户端设置连接、读取与总超时；重试只用于可安全重放的操作，并配合退避、抖动和幂等键。线程池、连接池和队列都必须有界，降级结果应与正常结果在类型和监控上可区分。</p>\n      <h2>可观测性与发布</h2>\n      <p>Actuator 提供健康与运行端点，Micrometer 负责指标与追踪桥接。健康检查区分存活和就绪，指标避免把用户 ID 放入标签造成高基数。容器镜像固定依赖和基础镜像摘要，并在发布前验证迁移、滚动升级和回滚。</p>\n      <h2>一手资料</h2><ul><li><a href="https://docs.spring.io/spring-boot/reference/" target="_blank" rel="noopener noreferrer">Spring Boot 4.1 Reference</a></li><li><a href="https://docs.spring.io/spring-boot/reference/actuator/index.html" target="_blank" rel="noopener noreferrer">Spring Boot Actuator</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> the stable Spring Boot 4.1 line. Before upgrading, verify the Java baseline, Spring Framework, Jakarta namespaces, and third-party starters.</p>\n      <h2>Auto-configuration is inspectable</h2><p>Conditions based on the classpath, beans, and properties create infrastructure. Production diagnosis must identify which condition created a bean and which property source won.</p>\n      <h2>Bound failure</h2><p>Set connection, read, and total timeouts. Retry only safely replayable work with backoff, jitter, and idempotency. Pools and queues must be bounded.</p>\n      <h2>Observe and release</h2><p>Use Actuator health endpoints and Micrometer telemetry, separate liveness from readiness, control metric cardinality, and validate migrations, rolling upgrades, and rollback.</p>\n      <h2>Primary sources</h2><ul><li><a href="https://docs.spring.io/spring-boot/reference/" target="_blank" rel="noopener noreferrer">Spring Boot 4.1 Reference</a></li><li><a href="https://docs.spring.io/spring-boot/reference/actuator/index.html" target="_blank" rel="noopener noreferrer">Spring Boot Actuator</a></li></ul>\n    '},6:{builtInRevision:3,translationOverride:!0,date:"2026-07-12",category:"大模型系统",categoryEn:"ML Systems",readTime:18,readTimeEn:18,title:"大模型推理工程：KV Cache、批处理、量化与延迟预算",titleEn:"LLM Inference Engineering: KV Cache, Batching, Quantization, and Latency Budgets",excerpt:"从 prefill 与 decode 两阶段出发，解释 KV Cache 为什么主导显存，连续批处理和 PagedAttention 如何提高吞吐，以及量化带来的质量与硬件权衡。",excerptEn:"Start with prefill and decode, then examine why KV cache dominates memory, how continuous batching and PagedAttention improve throughput, and what quantization trades away.",content:'\n      <p><strong>适用范围：</strong>自托管或专用实例上的自回归大语言模型推理。任何吞吐数字都依赖模型、上下文长度、硬件、精度和流量分布，不能跨环境直接比较。</p>\n      <h2>Prefill 与 Decode 是两种负载</h2>\n      <p>Prefill 并行处理输入 Token，通常更偏计算密集；Decode 每一步只生成少量 Token，却不断读取 KV Cache，更容易受显存带宽和调度影响。应分别记录 TTFT、每输出 Token 延迟和完整请求时延。</p>\n      <h2>KV Cache 与连续批处理</h2>\n      <p>KV Cache 随层数、上下文和并发增长。静态预留会产生碎片，PagedAttention 借鉴虚拟内存分页管理缓存块；连续批处理则在请求完成后立即填入新请求，提高设备利用率，但可能让尾延迟恶化。</p>\n      <h2>量化与服务目标</h2>\n      <p>权重量化减少显存和带宽，但不同模型、任务和硬件的精度损失不同。先定义质量阈值、P95/P99 延迟、吞吐和成本，再选择精度、最大上下文、批大小和并发策略。过载时应排队、拒绝或降级，而不是无限扩大批次。</p>\n      <h2>一手资料</h2><ul><li><a href="https://arxiv.org/abs/2309.06180" target="_blank" rel="noopener noreferrer">PagedAttention / vLLM 原始论文</a></li><li><a href="https://docs.vllm.ai/en/latest/" target="_blank" rel="noopener noreferrer">vLLM Documentation</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> autoregressive LLM serving on self-hosted or dedicated infrastructure. Throughput numbers depend on model, context, hardware, precision, and traffic distribution.</p>\n      <h2>Prefill and decode differ</h2><p>Prefill processes prompt tokens in parallel and is often compute-heavy. Decode repeatedly reads KV cache and is commonly sensitive to memory bandwidth and scheduling. Measure TTFT, inter-token latency, and end-to-end latency separately.</p>\n      <h2>KV cache and batching</h2><p>PagedAttention manages cache blocks like virtual-memory pages; continuous batching admits work as other requests finish. Both improve utilization but can worsen tail latency without admission control.</p>\n      <h2>Primary sources</h2><ul><li><a href="https://arxiv.org/abs/2309.06180" target="_blank" rel="noopener noreferrer">PagedAttention / vLLM paper</a></li><li><a href="https://docs.vllm.ai/en/latest/" target="_blank" rel="noopener noreferrer">vLLM Documentation</a></li></ul>\n    '},7:{builtInRevision:3,translationOverride:!0,date:"2026-07-08",category:"云原生",categoryEn:"Cloud Native",readTime:16,readTimeEn:16,title:"云原生系统设计：Kubernetes 控制循环与 OpenTelemetry",titleEn:"Cloud-Native System Design: Kubernetes Control Loops and OpenTelemetry",excerpt:"从 Kubernetes 的期望状态与控制循环理解调度和自愈，再用 OpenTelemetry 统一追踪、指标和日志，建立面向 SLO 的运行体系。",excerptEn:"Understand scheduling and recovery through Kubernetes desired state and control loops, then use OpenTelemetry signals to operate services against explicit SLOs.",content:'\n      <p><strong>适用范围：</strong>运行在 Kubernetes 上的有状态或无状态服务。云原生不是“把应用放进容器”，而是把部署、恢复、观测和变更都设计成声明式、可重复过程。</p>\n      <h2>控制循环是核心抽象</h2>\n      <p>对象的 spec 描述期望状态，status 反映当前状态，控制器持续缩小两者差异。请求和限制影响调度与隔离；探针、优雅终止、PodDisruptionBudget 和滚动策略共同决定升级期间是否保持服务。</p>\n      <h2>不要把瞬时文件系统当数据库</h2>\n      <p>容器可以随时重建，持久数据必须进入数据库、对象存储或明确的持久卷。服务需要处理重复启动、终止信号、连接排空和正在执行任务的恢复。</p>\n      <h2>三类遥测信号</h2>\n      <p>Trace 解释单次请求路径，Metric 观察聚合趋势，Log 记录离散事件。OpenTelemetry 通过上下文传播关联信号；指标标签必须限制基数，原始 URL、用户 ID 和请求 ID 不应直接成为维度。</p>\n      <h2>一手资料</h2><ul><li><a href="https://kubernetes.io/docs/concepts/overview/working-with-objects/" target="_blank" rel="noopener noreferrer">Kubernetes Objects and desired state</a></li><li><a href="https://opentelemetry.io/docs/concepts/" target="_blank" rel="noopener noreferrer">OpenTelemetry Concepts</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> stateless and stateful workloads on Kubernetes. Cloud native means deployment, recovery, observation, and change are declarative and repeatable—not merely containerized.</p>\n      <h2>Control loops</h2><p>The spec declares desired state, status reports current state, and controllers continuously reconcile the difference. Resources, probes, graceful shutdown, disruption budgets, and rollout policy jointly determine availability.</p>\n      <h2>Telemetry signals</h2><p>Traces explain request paths, metrics show aggregate trends, and logs record events. OpenTelemetry correlates them through context propagation; metric attributes require strict cardinality control.</p>\n      <h2>Primary sources</h2><ul><li><a href="https://kubernetes.io/docs/concepts/overview/working-with-objects/" target="_blank" rel="noopener noreferrer">Kubernetes Objects</a></li><li><a href="https://opentelemetry.io/docs/concepts/" target="_blank" rel="noopener noreferrer">OpenTelemetry Concepts</a></li></ul>\n    '},8:{builtInRevision:3,translationOverride:!0,date:"2026-07-04",category:"分布式系统",categoryEn:"Distributed Systems",readTime:17,readTimeEn:17,title:"分布式一致性实践：幂等、Outbox、共识与故障恢复",titleEn:"Distributed Consistency in Practice: Idempotency, Outbox, Consensus, and Recovery",excerpt:"从网络不可靠和重复投递的现实出发，区分事务原子性、消息一致性与共识问题，并用幂等键、Transactional Outbox 和可重放事件构建恢复路径。",excerptEn:"Start from unreliable networks and duplicate delivery. Separate database atomicity, messaging consistency, and consensus, then design recovery with idempotency, outbox, and replayable events.",content:'\n      <p><strong>适用范围：</strong>数据库、消息队列和多个服务共同完成业务操作的系统。本文默认网络会超时、消息会重复、进程会在任意一步崩溃。</p>\n      <h2>“Exactly once”需要定义观察范围</h2>\n      <p>消息系统可以降低重复概率或在自身边界内去重，但业务副作用仍可能重复执行。消费者应使用消息 ID 或业务幂等键，在同一数据库事务中记录处理结果；支付、库存等操作还要定义重复请求返回什么。</p>\n      <h2>Transactional Outbox</h2>\n      <p>业务数据与待发送事件写入同一数据库事务，由独立发布器把 outbox 记录投递到消息系统。它避免“数据库已提交但消息没发出”的双写裂缝，但消费者仍必须幂等，发布器也需要重试与清理策略。</p>\n      <h2>不要把共识用在所有地方</h2>\n      <p>共识协议解决多个节点对顺序和领导权达成一致，不等于跨服务自动获得业务事务。大多数业务流程更适合补偿、状态机和可重放事件。设计文档必须写明每个状态的权威来源以及部分失败后的恢复动作。</p>\n      <h2>故障演练</h2>\n      <p>主动注入超时、重复消息、乱序、发布器重启和数据库故障，验证不变量、积压恢复时间和人工处置流程。没有经过故障重放验证的一致性方案仍只是推测。</p>\n      <h2>参考资料</h2><ul><li><a href="https://microservices.io/patterns/data/transactional-outbox.html" target="_blank" rel="noopener noreferrer">Transactional Outbox Pattern</a></li><li><a href="https://microservices.io/patterns/communication-style/idempotent-consumer.html" target="_blank" rel="noopener noreferrer">Idempotent Consumer Pattern</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> operations spanning databases, queues, and multiple services. Assume networks time out, messages repeat, and processes can crash between any two steps.</p>\n      <h2>Define the boundary of “exactly once”</h2><p>A broker may deduplicate within its own boundary, but business side effects can still repeat. Consumers need message or business idempotency keys recorded in the same database transaction as the outcome.</p>\n      <h2>Transactional outbox</h2><p>Write business state and an outgoing event atomically, then let a publisher deliver outbox rows. This closes the database/message dual-write gap, but publishers still retry and consumers remain idempotent.</p>\n      <h2>Consensus is not a business transaction</h2><p>Consensus establishes ordering and leadership among nodes. Cross-service workflows usually need state machines, compensation, and replayable events with an explicit source of truth.</p>\n      <h2>References</h2><ul><li><a href="https://microservices.io/patterns/data/transactional-outbox.html" target="_blank" rel="noopener noreferrer">Transactional Outbox Pattern</a></li><li><a href="https://microservices.io/patterns/communication-style/idempotent-consumer.html" target="_blank" rel="noopener noreferrer">Idempotent Consumer Pattern</a></li></ul>\n    '}},r={1:{content:'\n      <p><strong>适用范围：</strong>使用代码代理、IDE 助手或对话模型维护真实软件仓库的个人与团队。“Vibe Coding”不是正式的软件工程标准，它描述的是一种以自然语言驱动实现的工作方式。真正的问题不是模型能否生成代码，而是生成结果能否进入可审计、可回滚、可维护的交付链路。</p>\n      <h2>一、先把 Vibe Coding 从“聊天”变成工程输入</h2>\n      <p>自然语言擅长表达目标，却天然缺少边界。比如“给登录页加记住密码”没有说明保存期限、加密方式、跨设备行为、退出登录后的清理规则和隐私要求。代理若直接动手，只能自行补全这些空白，而每一次自行补全都可能成为隐蔽的产品决定。</p>\n      <p>因此第一步不是写更长的提示词，而是建立仓库级上下文：技术栈与版本、目录职责、禁止修改区域、数据模型、测试命令、部署方式、安全约束以及当前工作树状态。任务提示只描述本次变化，稳定规则放在仓库文档中，避免每轮对话重新解释。</p>\n      <h2>二、五阶段交付闭环</h2>\n      <ol><li><strong>Context：</strong>读取相关代码、依赖、测试和历史约束，明确什么不能改。</li><li><strong>Plan：</strong>把目标改写为用户可观察结果，同时列出风险、回滚点与验证方法。</li><li><strong>Implement：</strong>按最小可审查单元修改，避免一次性重写整个模块。</li><li><strong>Verify：</strong>运行格式、类型、单元、集成、构建和关键路径浏览器测试。</li><li><strong>Review：</strong>检查权限扩大、数据破坏、依赖来源、异常路径与未来维护成本。</li></ol>\n      <p>这五步不是形式主义。它们分别回答“依据是什么、准备怎么改、实际改了什么、如何证明、谁承担责任”。缺少任何一步，模型输出都只能算草稿。</p>\n      <h2>三、把任务拆成可验证断言</h2>\n      <p>“优化性能”无法直接验证；“移动端首屏不请求 4K 视频、LCP 图片小于 100 KB、主要路由返回 200”才可以。每个任务至少包含一个正向断言、一个失败断言和一个不回归断言。例如新增导入功能时，需要证明合法文件能导入、损坏文件得到明确错误、既有数据不会被覆盖。</p>\n      <pre><code>目标：用户能从订单页导出 CSV\n边界：不改变数据库结构，不新增第三方依赖\n验证：\n1. 0、1、10000 条记录均生成合法 UTF-8 CSV\n2. 特殊字符和换行正确转义\n3. 无权限用户返回 403，不生成临时文件\n4. npm test 与生产构建通过</code></pre>\n      <h2>四、控制代理的修改半径</h2>\n      <p>优秀的代理也会误判。限制一次任务能修改的目录、文件数量和依赖范围，可以显著降低审查成本。涉及数据库迁移、鉴权、支付、删除和基础设施时，应要求代理先停在计划阶段；批量删除、强制推送和生产写操作必须保留人工授权。</p>\n      <p>对生成依赖同样保持怀疑：检查许可证、维护状态、锁文件变化、安装脚本和供应链风险。能用平台能力解决的问题，不应因为模型熟悉某个包就引入新依赖。</p>\n      <h2>五、AI 审查不能审判自己的答案</h2>\n      <p>可以让第二个代理检查差异，但不能把它当作独立证明。审查上下文可能与实现代理共享同样的误解。关键变更仍需静态分析、确定性测试、真实运行和领域责任人复核。AI 审查适合发现遗漏、重复、常见安全问题和未覆盖分支，不适合替代业务授权。</p>\n      <h2>六、如何衡量是否真的提高生产率</h2>\n      <p>不要只统计生成行数。更有价值的指标是从需求到通过检查的周期、首轮通过率、人工返工时间、缺陷逃逸率、回滚次数和半年后的维护成本。如果生成速度提高一倍，却让审查时间增加三倍或引入更多线上事故，整体生产率反而下降。</p>\n      <h2>七、可直接执行的团队清单</h2>\n      <ul><li>仓库规则、测试入口和安全边界是否可被代理读取？</li><li>任务是否被改写成可验证断言？</li><li>代理是否只修改授权范围？</li><li>是否展示并审查完整 diff，而非只看最终页面？</li><li>失败路径、取消、超时和回滚是否验证？</li><li>AI 生成部分是否仍有明确的人类责任人？</li></ul>\n      <h2>结论</h2>\n      <p>Vibe Coding 的专业化不是让提示词更华丽，而是让自然语言意图经过规格化、有限变更、确定性验证和责任审查。模型负责压缩实现时间，工程流程负责保护正确性。</p>\n      <h2>一手资料</h2><ul><li><a href="https://docs.github.com/en/copilot/how-tos/use-copilot-agents" target="_blank" rel="noopener noreferrer">GitHub Docs：Copilot agents</a></li><li><a href="https://docs.github.com/en/copilot/how-tos/use-copilot-agents/request-a-code-review" target="_blank" rel="noopener noreferrer">GitHub Docs：Copilot code review</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> individuals and teams using coding agents in real repositories. Vibe coding becomes engineering only when natural-language intent enters an auditable, reversible delivery system.</p>\n      <h2>From conversation to specification</h2><p>A request such as “remember login” omits retention, encryption, device scope, logout behavior, and privacy. Stable repository rules should define versions, ownership, tests, protected areas, and safety constraints; the task prompt should describe only the current change.</p>\n      <h2>The five-stage loop</h2><ol><li>Context: inspect code, dependencies, tests, and constraints.</li><li>Plan: define observable outcomes, risks, rollback, and evidence.</li><li>Implement: work in small reviewable units.</li><li>Verify: run deterministic checks and critical paths.</li><li>Review: inspect privilege, destructive behavior, supply chain, and maintainability.</li></ol>\n      <h2>Verifiable assertions</h2><p>Replace “make it faster” with measurable statements such as “mobile does not request 4K video, the LCP image is under 100 KB, and deep routes return 200.” Include success, failure, and non-regression cases.</p>\n      <h2>Control the change radius</h2><p>Limit directories, file count, and dependency changes. Database migrations, authentication, payments, deletion, and infrastructure should stop for explicit human approval before mutation.</p>\n      <h2>Independent evidence</h2><p>A second model can review a diff, but it can share the same mistaken premise. Static analysis, deterministic tests, runtime inspection, and accountable domain review remain necessary.</p>\n      <h2>Measure the outcome</h2><p>Track lead time to passing checks, first-pass success, human rework, escaped defects, rollback rate, and later maintenance—not generated lines.</p>\n      <h2>Primary sources</h2><ul><li><a href="https://docs.github.com/en/copilot/how-tos/use-copilot-agents" target="_blank" rel="noopener noreferrer">GitHub Docs: Copilot agents</a></li><li><a href="https://docs.github.com/en/copilot/how-tos/use-copilot-agents/request-a-code-review" target="_blank" rel="noopener noreferrer">GitHub Docs: Copilot code review</a></li></ul>\n    '},2:{content:'\n      <p><strong>适用范围：</strong>把大语言模型接入搜索、知识库、办公或业务系统的产品。模型版本会快速变化，因此架构应围绕能力接口、证据、权限和评测设计，而不是绑定单一模型名称。</p>\n      <h2>一、AI 应用不是一次普通 API 调用</h2>\n      <p>传统函数在相同输入下通常产生可预测结果，大模型输出则受模型版本、采样参数、上下文顺序和工具结果影响。生产系统必须接受这种概率性：模型负责候选推理，确定性代码负责权限、校验、金额、状态转换和最终写入。</p>\n      <p>先按风险划分任务。文案改写可以自动执行；内部知识问答需要引用证据；修改客户数据需要权限与确认；付款、删除和发布则必须保留确定性规则与人工审批。</p>\n      <h2>二、模型、RAG、工具与 Agent 的分工</h2>\n      <ul><li><strong>基础模型：</strong>语言理解、生成、分类和推理。</li><li><strong>RAG：</strong>检索外部知识并把证据注入上下文。</li><li><strong>工具调用：</strong>执行数据库查询、搜索、计算或业务 API。</li><li><strong>Agent：</strong>在多步任务中维护计划、状态、工具结果和停止条件。</li></ul>\n      <p>它们不是必须全部叠加。FAQ 可能只需检索与生成；航班改签需要受控工具；跨多个系统调查故障才可能需要 Agent。架构复杂度应由任务复杂度和风险决定。</p>\n      <h2>三、RAG 的六段质量链</h2>\n      <p>数据先清洗和分块，再生成索引；查询经过改写与过滤，召回候选后重排，最后构造带来源的上下文。失败可能发生在任一段：分块切断语义、元数据过滤错误、向量召回遗漏、重排偏差、上下文过长或模型忽略证据。</p>\n      <p>因此评测至少分为两层：检索层测 Recall@K、MRR 或人工相关性；回答层测事实正确、引用完整、拒答合理和是否忠实于证据。只给最终答案打分无法定位问题。</p>\n      <h2>四、Agent 必须是有界状态机</h2>\n      <p>生产 Agent 需要显式状态：目标、当前步骤、已完成操作、待确认动作、预算与终止原因。每个工具声明输入模式、权限和副作用。高风险操作使用最小权限凭据、参数白名单、幂等键和人工确认。</p>\n      <pre><code>while (!done &amp;&amp; steps &lt; MAX_STEPS &amp;&amp; cost &lt; BUDGET) {\n  const action = policy.next(state)\n  validate(action)\n  if (action.risk === \'high\') await requireHumanApproval(action)\n  state = await executeAndRecord(action, state)\n}</code></pre>\n      <h2>五、提示注入与数据边界</h2>\n      <p>检索文档、网页和工具返回值都属于不可信输入。系统不能因为文档中出现“忽略之前指令”就扩大权限。模型上下文与工具权限分离；敏感字段在进入模型前脱敏；输出在执行前做模式校验；不同租户的索引、缓存和日志严格隔离。</p>\n      <h2>六、评测闭环</h2>\n      <p>建立覆盖正常、边界、对抗和拒答场景的黄金集，记录模型、提示、检索器和工具版本。指标同时包含正确性、引用完整度、工具成功率、P95 延迟、单任务成本和安全违规。线上失败样本先脱敏和人工标注，再进入回归集。</p>\n      <h2>七、参考生产架构</h2>\n      <p>入口层负责身份与限流；编排层管理状态和预算；检索层提供带权限过滤的证据；工具网关执行白名单操作；模型网关统一版本、超时与费用；评测与可观测层记录完整 Trace。任何模型都可以替换，但授权和审计不能交给模型。</p>\n      <h2>结论</h2><p>AI 浪潮真正改变的是软件从确定性函数扩展到概率性组件。成熟架构不是追求“最聪明的 Agent”，而是让模型在证据充分、权限有限、失败可见的边界内工作。</p>\n      <h2>一手资料</h2><ul><li><a href="https://www.nist.gov/itl/ai-risk-management-framework" target="_blank" rel="noopener noreferrer">NIST AI Risk Management Framework</a></li><li><a href="https://arxiv.org/abs/2005.11401" target="_blank" rel="noopener noreferrer">Retrieval-Augmented Generation 原始论文</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> products connecting LLMs to search, knowledge, and business systems. Architecture should center on evidence, authorization, evaluation, and replaceable model interfaces.</p>\n      <h2>Probabilistic components need deterministic boundaries</h2><p>Models propose language and reasoning; deterministic code owns authorization, validation, money, state transitions, and writes. Risk determines whether a task may execute automatically.</p>\n      <h2>Four distinct capabilities</h2><p>Models generate, RAG supplies evidence, tools perform deterministic operations, and agents maintain state across steps. Use only the complexity the task requires.</p>\n      <h2>The RAG quality chain</h2><p>Cleaning, chunking, indexing, query rewriting, retrieval, reranking, context construction, and citation can each fail. Evaluate retrieval separately from final answers to locate the defect.</p>\n      <h2>Agents as bounded state machines</h2><p>Persist goals, steps, results, approvals, budgets, and termination reasons. Validate tool schemas, apply least privilege and idempotency, and cap steps, tokens, cost, and time.</p>\n      <h2>Security and evaluation</h2><p>Treat retrieved text and tool results as untrusted. Separate model context from authority, isolate tenants, redact sensitive data, and validate outputs before execution. Maintain golden, boundary, adversarial, and refusal datasets.</p>\n      <h2>Primary sources</h2><ul><li><a href="https://www.nist.gov/itl/ai-risk-management-framework" target="_blank" rel="noopener noreferrer">NIST AI RMF</a></li><li><a href="https://arxiv.org/abs/2005.11401" target="_blank" rel="noopener noreferrer">Original RAG paper</a></li></ul>\n    '},3:{content:'\n      <p><strong>适用范围：</strong>Java 25 LTS 服务端应用。虚拟线程是正式能力；结构化并发在此基线下仍应按预览能力管理，生产采用前必须核对编译参数、框架支持和升级策略。</p>\n      <h2>一、平台线程为什么会成为瓶颈</h2>\n      <p>传统平台线程通常映射到操作系统线程，创建和上下文切换成本较高。阻塞式 Web 服务为每个请求占用一个线程，当大量请求等待数据库或网络时，线程数、栈内存和调度成本快速增长。异步回调能减少线程占用，却把控制流、异常和上下文传播拆散。</p>\n      <h2>二、虚拟线程解决的是等待成本</h2>\n      <p>虚拟线程由 JVM 调度到少量载体线程上。执行阻塞式 I/O 时，虚拟线程可以卸载，让载体线程运行其他任务，从而保留清晰的顺序代码并支撑更高并发。它不会减少一次 SQL 的耗时，也不会让 CPU 密集计算变快。</p>\n      <pre><code>try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {\n  Future&lt;User&gt; user = executor.submit(() -&gt; users.find(id));\n  Future&lt;List&lt;Order&gt;&gt; orders = executor.submit(() -&gt; orderClient.load(id));\n  return new Profile(user.get(), orders.get());\n}</code></pre>\n      <h2>三、吞吐仍由最窄资源决定</h2>\n      <p>如果数据库连接池只有 50 个连接，创建 10 万个虚拟线程只会让更多请求排队。连接池、下游限流、文件句柄、CPU 和内存仍需有界。虚拟线程取消了“线程很贵”这一部分约束，没有取消背压。</p>\n      <h2>四、结构化并发让生命周期可推理</h2>\n      <p>结构化并发把相关子任务放在同一作用域：父任务在离开作用域前等待子任务，某个子任务失败时按策略取消其他任务，异常回到调用者。相比把 Future 丢进全局线程池，它更容易回答“谁创建、谁等待、失败后谁取消”。</p>\n      <p>常见策略包括全部成功、首个成功和失败即取消。超时应该作用于整个业务请求，而不是每个子任务各自计时导致总时长失控。</p>\n      <h2>五、ThreadLocal、固定与兼容性</h2>\n      <p>大量虚拟线程会放大 ThreadLocal 大对象的内存成本。上下文应尽量小而不可变。同步块、本地方法和旧驱动过去可能造成载体线程固定，需要结合目标 JDK 与依赖版本实际分析，而不是照搬早期结论。</p>\n      <h2>六、迁移路线</h2>\n      <ol><li>选取 I/O 密集、调用链清晰的接口建立基线。</li><li>升级驱动和框架，确认其阻塞语义与虚拟线程支持。</li><li>保持数据库和 HTTP 并发上限，不盲目放大连接池。</li><li>用 JFR、线程转储与压测比较平台线程和虚拟线程。</li><li>逐步替换手工异步回调，并保留超时、取消与背压。</li></ol>\n      <h2>七、验证指标</h2>\n      <p>同时观察吞吐、P50/P95/P99、连接池等待、CPU、堆外内存、GC、载体线程利用率和取消响应。只有在相同数据与下游容量下比较才有意义。</p>\n      <h2>结论</h2><p>虚拟线程让阻塞式 Java 再次具备高并发竞争力；结构化并发让并发任务重新拥有清晰的父子关系。但容量规划、背压和故障边界仍然是系统设计问题，不能交给线程模型自动解决。</p>\n      <h2>一手资料</h2><ul><li><a href="https://docs.oracle.com/en/java/javase/25/core/virtual-threads.html" target="_blank" rel="noopener noreferrer">Oracle Java 25：Virtual Threads</a></li><li><a href="https://docs.oracle.com/en/java/javase/25/core/structured-concurrency.html" target="_blank" rel="noopener noreferrer">Oracle Java 25：Structured Concurrency</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> Java 25 LTS server software. Virtual threads are permanent; structured concurrency remains a preview capability in this baseline.</p>\n      <h2>What virtual threads solve</h2><p>Platform threads are expensive when thousands of requests wait on I/O. Virtual threads let the JVM unmount blocked work from carrier threads, preserving sequential code without paying one operating-system thread per request.</p>\n      <h2>What they do not solve</h2><p>Database pools, downstream quotas, CPU, file descriptors, and memory remain bounded. One hundred thousand virtual threads waiting for fifty connections is still overload.</p>\n      <h2>Structured concurrency</h2><p>Related subtasks share a lexical scope. The parent joins them, failure can cancel siblings, and exceptions return through the call tree. Apply one deadline to the business operation instead of unrelated child timeouts.</p>\n      <h2>Migration and evidence</h2><p>Begin with I/O-heavy endpoints, update drivers, retain concurrency limits, and compare throughput, tail latency, pool waits, CPU, memory, GC, and cancellation using JFR and load tests.</p>\n      <h2>Primary sources</h2><ul><li><a href="https://docs.oracle.com/en/java/javase/25/core/virtual-threads.html" target="_blank" rel="noopener noreferrer">Oracle: Virtual Threads</a></li><li><a href="https://docs.oracle.com/en/java/javase/25/core/structured-concurrency.html" target="_blank" rel="noopener noreferrer">Oracle: Structured Concurrency</a></li></ul>\n    '},4:{content:'\n      <p><strong>适用范围：</strong>MySQL 8.4 LTS、InnoDB。本文给出从存储结构到线上诊断的完整路径。所有优化结论都必须由真实数据分布、执行计划和等价负载验证，不能只根据 SQL 外观判断。</p>\n      <h2>一、InnoDB 如何组织一张表</h2>\n      <p>InnoDB 以页为基本存储单位，用 B+Tree 组织索引。主键索引是聚簇索引：叶子节点直接保存整行；二级索引叶子保存索引列和主键值。因此通过二级索引查询非覆盖列时，需要先找到主键再回到聚簇索引。</p>\n      <p>这个结构带来三个直接结论：主键应稳定且尽量紧凑；每增加一个二级索引都会增加写放大和存储；宽主键会被复制到所有二级索引中。索引不是越多越好，而是用写入成本换取特定读取路径。</p>\n      <h2>二、联合索引应该围绕访问路径设计</h2>\n      <p>假设订单常按租户、状态和创建时间查询：</p>\n      <pre><code>SELECT id, amount, created_at\nFROM orders\nWHERE tenant_id = ? AND status = ?\nORDER BY created_at DESC\nLIMIT 50;</code></pre>\n      <p><code>(tenant_id, status, created_at)</code> 可以同时服务过滤与排序，但是否值得仍取决于状态分布、租户大小和查询比例。若还要返回 amount，可考虑覆盖索引，但索引宽度和写入成本也会增加。应通过 <code>EXPLAIN ANALYZE</code> 观察实际扫描行数，而不是只看是否出现 key 名称。</p>\n      <h2>三、MVCC 如何提供一致性读</h2>\n      <p>InnoDB 通过事务 ID、undo 记录与 Read View 判断某个版本对当前事务是否可见。一致性读通常读取快照，不必阻塞普通写入；当前读、更新和删除仍需要锁。MVCC 减少读写冲突，但没有消灭锁。</p>\n      <p>长事务会让旧版本长期无法清理，增加 undo 压力并拖慢清理、复制和备份。事务开启后不应等待用户输入、远程接口或长时间计算。先完成外部准备，再进入尽可能短的数据库事务。</p>\n      <h2>四、隔离级别与锁范围</h2>\n      <p>READ COMMITTED 每次一致性读通常建立新快照；REPEATABLE READ 在事务内维持一致视图。锁定读如 <code>FOR UPDATE</code> 获取当前版本并加锁，其范围受到访问索引和条件影响。缺少合适索引时，锁范围可能远大于业务预期。</p>\n      <p>不要把“加锁”当作唯一并发控制。唯一约束、版本号乐观锁和幂等键往往更直接。使用悲观锁时要固定加锁顺序、缩短事务并为死锁重试做好准备。</p>\n      <h2>五、读懂 EXPLAIN ANALYZE</h2>\n      <ol><li>从慢查询日志或 Performance Schema 找到真实高成本语句。</li><li>核对估算行数与实际行数，巨大偏差通常指向统计信息或数据倾斜。</li><li>查看每个算子的循环次数；内层循环很小的单次成本也可能被放大。</li><li>检查是否出现临时表、文件排序、回表和大范围扫描。</li><li>用生产相似数据重放，不在空库上得出结论。</li></ol>\n      <h2>六、死锁与锁等待不是同一个问题</h2>\n      <p>锁等待可能最终成功，只是超过延迟预算；死锁形成等待环，数据库必须回滚其中一个事务。诊断时保存死锁信息、涉及 SQL、索引、事务顺序和持锁时间。应用必须能安全重试被选中的事务，但重试次数要有上限。</p>\n      <h2>七、连接池、提交与容量</h2>\n      <p>连接数过多会增加内存和调度成本。池大小应由数据库可承受并发和查询耗时决定，而不是 Web 请求数。过度频繁提交增加日志刷盘压力；过大的事务又会扩大锁和恢复成本。通过批量边界找到吞吐与延迟的平衡。</p>\n      <h2>八、线上诊断运行手册</h2>\n      <ul><li>确认症状：延迟、错误率、锁等待还是 CPU/IO 饱和。</li><li>定位贡献最大的 SQL，而不是先猜索引。</li><li>检查执行计划、数据分布、事务与锁。</li><li>在副本或等价环境验证索引与 SQL 修改。</li><li>观察写放大、缓存命中和复制延迟等副作用。</li><li>保留回滚方案，避免高峰期执行不可控 DDL。</li></ul>\n      <h2>结论</h2><p>MySQL 优化不是背诵“最左匹配”或不断加索引，而是理解数据如何落在页和树中、事务如何看到版本、优化器如何估算成本，并用真实观测逐层排除问题。</p>\n      <h2>一手资料</h2><ul><li><a href="https://dev.mysql.com/doc/refman/8.4/en/innodb-storage-engine.html" target="_blank" rel="noopener noreferrer">MySQL 8.4：InnoDB Storage Engine</a></li><li><a href="https://dev.mysql.com/doc/refman/8.4/en/explain.html" target="_blank" rel="noopener noreferrer">MySQL 8.4：EXPLAIN</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> MySQL 8.4 LTS with InnoDB. Claims require real distributions, execution plans, and equivalent workload.</p>\n      <h2>Storage first</h2><p>InnoDB stores clustered rows in primary-key B+Tree leaves. Secondary leaves contain indexed columns plus the primary key, so wide primary keys amplify every secondary index and non-covering reads require another lookup.</p>\n      <h2>Indexes follow access paths</h2><p>Design composite indexes around filtering, ordering, selectivity, and returned columns. Coverage reduces lookups but increases index size and write cost. EXPLAIN ANALYZE must confirm actual rows and loops.</p>\n      <h2>MVCC and locks</h2><p>Read views and undo versions provide consistent reads; current reads and writes still lock. Long transactions retain old versions and increase purge, replication, and recovery pressure.</p>\n      <h2>Diagnosis</h2><p>Start with slow-query or Performance Schema evidence. Compare estimates with actual rows, inspect loop counts, temporary tables, sorting, transactions, waits, and deadlocks. Reproduce with production-like data.</p>\n      <h2>Capacity</h2><p>Pool size follows database concurrency, not HTTP request count. Frequent commits increase log flushes; huge transactions increase lock and recovery cost. Measure the balance.</p>\n      <h2>Primary sources</h2><ul><li><a href="https://dev.mysql.com/doc/refman/8.4/en/innodb-storage-engine.html" target="_blank" rel="noopener noreferrer">MySQL 8.4: InnoDB</a></li><li><a href="https://dev.mysql.com/doc/refman/8.4/en/explain.html" target="_blank" rel="noopener noreferrer">MySQL 8.4: EXPLAIN</a></li></ul>\n    '},5:{content:'\n      <p><strong>适用范围：</strong>Spring Boot 4.1 稳定线的生产服务。升级前必须检查 Java 基线、Spring Framework、Jakarta 命名空间和第三方 starter 兼容性。生产级并不等于依赖更多组件，而是每个运行边界都可解释、可观测和可恢复。</p>\n      <h2>一、自动配置是条件系统，不是魔法</h2>\n      <p>Spring Boot 根据 classpath、Bean、属性和环境条件装配基础设施。排查问题时必须能回答某个 Bean 为什么存在、为什么没有创建、哪个配置源覆盖了值。使用类型化 <code>@ConfigurationProperties</code> 与校验，避免散落的字符串键和启动后才暴露的配置错误。</p>\n      <h2>二、建立清晰的应用边界</h2>\n      <p>控制器处理协议与校验，应用服务编排用例，领域层表达业务不变量，基础设施层实现数据库与外部系统。不要让 Controller 直接拼接 SQL，也不要让 JPA Entity 成为所有层共享的 API 模型。边界清晰后，事务、重试和测试才有明确位置。</p>\n      <h2>三、事务只覆盖本地一致性</h2>\n      <p><code>@Transactional</code> 管理代理拦截范围内的本地资源，不能自动把 HTTP 调用和消息队列变成分布式事务。自调用、异常捕获和错误传播都会影响回滚。事务内避免长时间远程调用；数据库提交与消息发布使用 Outbox 或明确补偿。</p>\n      <pre><code>@Transactional\npublic Order create(Command command) {\n  Order order = orders.save(Order.create(command));\n  outbox.append(OrderCreated.from(order));\n  return order;\n}</code></pre>\n      <h2>四、超时、重试与隔离</h2>\n      <p>HTTP 客户端分别设置连接、读取和总时限。重试只适用于幂等或带幂等键的操作，并使用指数退避与抖动。线程池、连接池、队列和批量大小全部有界；熔断器保护系统免受持续失败拖累，但不能修复错误业务逻辑。</p>\n      <h2>五、可观测性必须围绕用户请求</h2>\n      <p>Actuator 暴露健康与运行信息，Micrometer 连接指标和追踪。区分 liveness 与 readiness：前者表示进程是否应重启，后者表示能否接收新流量。日志包含 traceId、业务操作与稳定错误码，不记录令牌和敏感数据。</p>\n      <p>指标标签避免用户 ID、订单号和原始 URL 等高基数值。告警围绕错误率、延迟和饱和度，并与 SLO 对齐，而不是监控所有可采集数字。</p>\n      <h2>六、安全默认值</h2>\n      <p>认证与授权分离，方法级权限不能只依赖前端隐藏按钮。CSRF、CORS、会话、OAuth2 资源服务器和 Secret 管理必须根据部署模型配置。错误响应不泄漏堆栈、SQL 或内部地址。</p>\n      <h2>七、容器、AOT 与发布</h2>\n      <p>镜像采用分层构建并固定基础镜像摘要；进程正确响应 SIGTERM，停止接收流量后等待在途请求。AOT 或原生镜像可能改善启动与内存，但会改变反射、动态代理和资源加载假设，应通过完整集成测试决定是否采用。</p>\n      <h2>八、上线清单</h2>\n      <ul><li>配置在启动时校验，Secret 不进入镜像和日志。</li><li>迁移与应用版本兼容滚动升级。</li><li>所有外部调用有超时、并发上限与失败指标。</li><li>健康检查不会因非关键依赖短暂波动导致重启风暴。</li><li>日志、指标和追踪能关联一次用户请求。</li><li>发布前演练回滚、数据库兼容和优雅终止。</li></ul>\n      <h2>结论</h2><p>Spring Boot 的优势是统一约定和生态，但生产可靠性来自理解这些约定背后的条件、事务和运行边界。能启动只是起点，能诊断、能降级、能安全升级才是完成。</p>\n      <h2>一手资料</h2><ul><li><a href="https://docs.spring.io/spring-boot/reference/" target="_blank" rel="noopener noreferrer">Spring Boot 4.1 Reference</a></li><li><a href="https://docs.spring.io/spring-boot/reference/actuator/index.html" target="_blank" rel="noopener noreferrer">Spring Boot Actuator</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> production services on the stable Spring Boot 4.1 line. Production quality means runtime boundaries are explainable, observable, and recoverable.</p>\n      <h2>Inspectable auto-configuration</h2><p>Classpath, bean, property, and environment conditions create infrastructure. Use typed, validated configuration and know which property source won.</p>\n      <h2>Application boundaries</h2><p>Controllers own protocol and validation, application services orchestrate use cases, domain code owns invariants, and infrastructure implements storage and integrations. Avoid exposing persistence entities as API models.</p>\n      <h2>Transactions</h2><p>@Transactional covers local resources inside the proxy boundary. It does not make HTTP calls and messaging atomic. Keep transactions short and use outbox or compensation for cross-system work.</p>\n      <h2>Resilience and observability</h2><p>Set connect, read, and total deadlines; retry only idempotent work; bound every pool and queue. Separate liveness from readiness, correlate logs, metrics, and traces, and control metric cardinality.</p>\n      <h2>Release</h2><p>Pin images, validate migrations, handle SIGTERM, drain traffic, and rehearse rollback. Adopt AOT or native images only after integration testing reflection and proxy assumptions.</p>\n      <h2>Primary sources</h2><ul><li><a href="https://docs.spring.io/spring-boot/reference/" target="_blank" rel="noopener noreferrer">Spring Boot 4.1 Reference</a></li><li><a href="https://docs.spring.io/spring-boot/reference/actuator/index.html" target="_blank" rel="noopener noreferrer">Spring Boot Actuator</a></li></ul>\n    '},6:{content:'\n      <p><strong>适用范围：</strong>自托管或专用实例上的自回归大语言模型推理。任何性能数字都依赖模型、上下文、输出长度、硬件、精度和流量分布，不能从论文或他人环境直接复制。</p>\n      <h2>一、一次生成包含两个不同阶段</h2>\n      <p>Prefill 并行处理输入 Token，建立每层的 KV Cache，通常更偏计算密集；Decode 每一步生成一个或少量 Token，不断读取已有 KV Cache，更容易受显存带宽、批处理和调度影响。用户看到的首字延迟主要受 Prefill 与排队影响，后续流畅度取决于每 Token 延迟。</p>\n      <h2>二、KV Cache 为什么迅速占满显存</h2>\n      <p>每个请求都要为每一层保存 Key 与 Value。粗略容量与层数、KV heads、head dimension、上下文长度和精度字节数成正比。长上下文和高并发同时增长时，缓存可能比权重更早成为瓶颈。GQA/MQA、低精度 Cache 和前缀复用可以降低成本，但都需要质量与兼容性验证。</p>\n      <pre><code>KV bytes per request ≈\n2 × layers × kv_heads × head_dim × sequence_length × bytes_per_element</code></pre>\n      <h2>三、PagedAttention 与连续批处理</h2>\n      <p>传统静态预留会因不同序列长度产生碎片。PagedAttention 借鉴虚拟内存分页，把 KV Cache 分成块并按需映射，提高有效容量。连续批处理不等待整批请求全部结束，而是在序列完成后立即接纳新请求，从而提高设备利用率。</p>\n      <p>吞吐提升并非免费：更大的批可能增加排队和尾延迟。调度器需要区分交互式与离线流量，设置最大并发、最大批 Token、抢占和公平策略。</p>\n      <h2>四、量化是一组权衡</h2>\n      <p>权重量化减少显存和内存带宽，激活与 KV Cache 量化进一步节省资源，但误差可能集中在特定任务。不要只测通用基准；应使用业务数据比较正确率、拒答、工具参数和长上下文稳定性。硬件是否有高效内核往往比理论位宽更重要。</p>\n      <h2>五、把延迟拆成预算</h2>\n      <p>端到端延迟包含网关、排队、分词、Prefill、Decode、工具调用和网络传输。分别记录排队时间、TTFT、ITL、输出 Token 数和完成原因，才能知道优化模型、调度还是上游缓存。</p>\n      <h2>六、过载保护</h2>\n      <p>GPU 饱和后继续接收请求只会让所有用户更慢。服务需要并发上限、优先级队列、超时、取消传播和明确拒绝。可选降级包括缩短上下文、降低最大输出、切换更小模型或转入异步任务，但必须向调用方暴露降级状态。</p>\n      <h2>七、生产评测矩阵</h2>\n      <ul><li>质量：业务正确率、长上下文、工具参数与安全拒答。</li><li>延迟：TTFT、ITL、P50/P95/P99 和排队时间。</li><li>吞吐：每秒请求、输入/输出 Token 与设备利用率。</li><li>成本：每百万 Token、每成功任务和空闲容量。</li><li>稳定性：OOM、取消、超时、重启恢复和多租户公平。</li></ul>\n      <h2>结论</h2><p>大模型推理不是简单“把模型放到 GPU”。它是内存管理、调度、数值精度、流量控制和产品延迟目标共同作用的系统工程。</p>\n      <h2>一手资料</h2><ul><li><a href="https://arxiv.org/abs/2309.06180" target="_blank" rel="noopener noreferrer">PagedAttention / vLLM 原始论文</a></li><li><a href="https://docs.vllm.ai/en/latest/" target="_blank" rel="noopener noreferrer">vLLM Documentation</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> autoregressive LLM serving on dedicated infrastructure. Results depend on model, context, output length, hardware, precision, and traffic.</p>\n      <h2>Prefill and decode</h2><p>Prefill processes prompt tokens in parallel and creates KV cache. Decode repeatedly reads that cache to emit tokens. Measure queue time, TTFT, inter-token latency, and end-to-end latency separately.</p>\n      <h2>KV cache pressure</h2><p>Memory scales with layers, KV heads, head dimension, sequence length, precision, and concurrency. GQA/MQA, cache quantization, and prefix reuse trade memory for compatibility and quality.</p>\n      <h2>Scheduling</h2><p>PagedAttention reduces fragmentation by mapping cache blocks on demand. Continuous batching admits new work as sequences finish, improving utilization while potentially increasing tail latency. Separate interactive and batch traffic.</p>\n      <h2>Quantization and overload</h2><p>Evaluate quantization on business tasks and actual hardware kernels. Enforce admission limits, priorities, deadlines, cancellation, and visible degradation rather than accepting unlimited work.</p>\n      <h2>Primary sources</h2><ul><li><a href="https://arxiv.org/abs/2309.06180" target="_blank" rel="noopener noreferrer">PagedAttention paper</a></li><li><a href="https://docs.vllm.ai/en/latest/" target="_blank" rel="noopener noreferrer">vLLM Documentation</a></li></ul>\n    '},7:{content:'\n      <p><strong>适用范围：</strong>运行在 Kubernetes 上的有状态或无状态服务。云原生不是“把应用放进容器”，而是把部署、恢复、观测与变更设计成声明式、可重复、可自动验证的过程。</p>\n      <h2>一、Kubernetes 的核心是控制循环</h2>\n      <p>对象的 spec 描述期望状态，status 反映当前状态，控制器持续比较两者并执行调谐。Deployment 不是“启动三个容器”的脚本，而是持续保证三个可用副本的意图。理解这一点后，故障恢复和滚动更新才不再神秘。</p>\n      <h2>二、调度依赖请求，而不是历史使用量</h2>\n      <p>调度器主要根据资源 requests 选择节点，limits 约束容器使用上限。请求设置过低会导致节点过度承诺和争抢；过高则浪费容量。CPU 限制可能带来节流，内存超限通常直接 OOM。应使用真实工作负载分布设置请求，并通过自动扩缩容逐步调整。</p>\n      <h2>三、探针和终止决定可用性</h2>\n      <p>startup probe 保护慢启动，readiness 决定是否接收流量，liveness 只判断进程是否需要重启。把所有下游依赖都塞进 liveness 会在依赖抖动时制造重启风暴。终止时先变为未就绪、停止接收新流量、处理 SIGTERM，再在宽限期内完成在途任务。</p>\n      <h2>四、状态不会因为容器化而消失</h2>\n      <p>容器文件系统是短暂的。数据库、对象存储或持久卷需要明确备份、恢复、扩容和故障域策略。StatefulSet 提供稳定身份和有序管理，但不自动保证数据库一致性；应用或数据库自身仍需复制与共识。</p>\n      <h2>五、安全发布</h2>\n      <p>滚动更新需要兼容旧新版本并存。数据库变更采用 expand-and-contract：先新增兼容结构，再部署读写兼容代码，最后清理旧结构。PodDisruptionBudget 保护计划内中断，反亲和和拓扑分布避免副本集中在同一故障域。</p>\n      <h2>六、OpenTelemetry 如何统一信号</h2>\n      <p>Trace 描述一次请求跨服务的路径，Metric 反映聚合趋势，Log 记录离散事件。上下文传播把三者关联起来。自动埋点提供基础覆盖，关键业务阶段仍需手工 Span 和稳定语义。</p>\n      <p>指标标签必须限制基数：服务、区域和状态码适合成为维度，用户 ID、订单号和原始 URL 不适合。高基数会造成内存、存储和查询成本失控。</p>\n      <h2>七、从监控转向 SLO</h2>\n      <p>先定义用户可观察的成功与延迟，再形成 SLI 和 SLO。错误预算连接可靠性与发布速度：预算消耗过快时优先修复稳定性，而不是继续增加变更。基础设施指标用于解释原因，不能替代用户层目标。</p>\n      <h2>八、故障演练</h2>\n      <ul><li>删除 Pod，验证流量切换与任务恢复。</li><li>使依赖超时，验证线程、连接和队列是否有界。</li><li>模拟节点不可用，验证副本是否跨故障域。</li><li>中断遥测后端，确保业务不会被观测系统拖垮。</li><li>执行回滚和数据恢复，记录实际恢复时间。</li></ul>\n      <h2>结论</h2><p>云原生系统的专业性不在 YAML 数量，而在期望状态、资源边界、发布兼容、遥测关联和故障恢复是否形成闭环。</p>\n      <h2>一手资料</h2><ul><li><a href="https://kubernetes.io/docs/concepts/overview/working-with-objects/" target="_blank" rel="noopener noreferrer">Kubernetes Objects and desired state</a></li><li><a href="https://opentelemetry.io/docs/concepts/" target="_blank" rel="noopener noreferrer">OpenTelemetry Concepts</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> stateful and stateless workloads on Kubernetes. Cloud native means deployment, recovery, observation, and change are declarative and repeatable.</p>\n      <h2>Control loops</h2><p>Spec declares intent, status reports reality, and controllers reconcile the difference. A Deployment continuously maintains availability rather than executing a one-time script.</p>\n      <h2>Resources and lifecycle</h2><p>Scheduling uses requests; limits constrain runtime. Mis-sizing causes contention or waste. Startup, readiness, and liveness answer different questions. Graceful termination must stop admission and drain in-flight work.</p>\n      <h2>State and release</h2><p>StatefulSet supplies identity, not database consistency. Backups, replication, and recovery remain application concerns. Use compatible rolling changes and expand-contract database migrations.</p>\n      <h2>OpenTelemetry and SLOs</h2><p>Correlate traces, metrics, and logs through context propagation, control metric cardinality, and define user-facing success and latency objectives before infrastructure alerts.</p>\n      <h2>Primary sources</h2><ul><li><a href="https://kubernetes.io/docs/concepts/overview/working-with-objects/" target="_blank" rel="noopener noreferrer">Kubernetes Objects</a></li><li><a href="https://opentelemetry.io/docs/concepts/" target="_blank" rel="noopener noreferrer">OpenTelemetry Concepts</a></li></ul>\n    '},8:{content:'\n      <p><strong>适用范围：</strong>数据库、消息队列和多个服务共同完成业务操作的系统。默认网络会超时、消息会重复、进程会在任意一步崩溃；如果设计只覆盖全部成功的路径，它就不是分布式设计。</p>\n      <h2>一、先写出系统不变量</h2>\n      <p>一致性不是抽象口号，而是业务必须始终成立的条件，例如余额不能凭空增加、订单只能完成一次、已扣库存最终必须对应订单或补偿。先写不变量，再决定哪些需要强事务、哪些允许短暂不一致以及最长恢复时间。</p>\n      <h2>二、本地事务与分布式事务的边界</h2>\n      <p>单个数据库事务可以原子提交本地数据，但无法原子覆盖一次 HTTP 调用和消息发布。常见错误是先写数据库再发消息：进程可能在两步之间崩溃；先发消息再写数据库同样存在反向裂缝。</p>\n      <h2>三、幂等是处理重复的业务协议</h2>\n      <p>“至少一次”投递意味着消费者会看到重复消息。消费者使用消息 ID 或业务幂等键，在与业务更新相同的数据库事务中记录处理结果。HTTP 创建接口也可接收幂等键，使客户端超时重试不会重复扣款或创建订单。</p>\n      <pre><code>BEGIN;\nINSERT INTO processed_message(consumer, message_id)\nVALUES (?, ?); -- unique constraint rejects duplicates\nUPDATE account SET balance = balance - ? WHERE id = ?;\nCOMMIT;</code></pre>\n      <h2>四、Transactional Outbox 关闭双写裂缝</h2>\n      <p>业务数据与待发送事件写入同一数据库事务。独立发布器读取 outbox 并投递，成功后标记或清理。这样数据库提交后事件不会永久丢失，但发布器可能重复投递，因此消费者仍需幂等。</p>\n      <h2>五、Saga 与补偿</h2>\n      <p>跨服务长流程通常拆成一组本地事务，由编排器或事件推进状态。失败时执行补偿，而补偿不是“数据库回滚”：退款、释放库存和撤销权益都是新的业务动作，也可能失败，需要重试、人工介入和审计。</p>\n      <h2>六、共识解决什么</h2>\n      <p>Raft 等共识协议让多个节点对日志顺序和领导权达成一致，用于复制状态机。它不自动解决订单、库存和支付之间的业务一致性。共识适合建立权威顺序与高可用元数据，不应被当作所有跨服务事务的万能方案。</p>\n      <h2>七、顺序、时钟与版本</h2>\n      <p>全局时间并不可靠。事件应携带实体版本或单调序号，消费者拒绝旧版本覆盖新状态。只在真正需要的实体范围内保证顺序，避免为不相关事件付出全局排序成本。</p>\n      <h2>八、可重放与可恢复</h2>\n      <p>事件载荷版本化，处理器支持旧版本，失败进入可观察的重试或死信流程。重放前明确副作用隔离，避免重新发送短信或扣款。每个工作流保留关联 ID、当前状态、最后成功步骤和人工处置入口。</p>\n      <h2>九、故障注入清单</h2>\n      <ul><li>数据库已提交但发布器立即崩溃。</li><li>同一消息连续投递多次或乱序到达。</li><li>消费者完成副作用后确认消息失败。</li><li>补偿服务不可用或只完成一部分。</li><li>网络分区后旧主节点重新加入。</li></ul>\n      <h2>结论</h2><p>分布式一致性的核心不是承诺“永不重复、永不失败”，而是明确权威状态、用幂等承受重复、用 Outbox 避免丢失、用状态机管理补偿，并确保每次失败都有可验证的恢复路径。</p>\n      <h2>参考资料</h2><ul><li><a href="https://microservices.io/patterns/data/transactional-outbox.html" target="_blank" rel="noopener noreferrer">Transactional Outbox Pattern</a></li><li><a href="https://microservices.io/patterns/communication-style/idempotent-consumer.html" target="_blank" rel="noopener noreferrer">Idempotent Consumer Pattern</a></li></ul>\n    ',contentEn:'\n      <p><strong>Scope:</strong> operations spanning databases, brokers, and multiple services. Assume timeouts, duplicate messages, reordering, and crashes between any two instructions.</p>\n      <h2>State invariants first</h2><p>Define what must remain true—money is not created, an order completes once, reserved stock ends in an order or compensation—then choose where strong or eventual consistency is acceptable.</p>\n      <h2>The dual-write gap</h2><p>A local transaction cannot atomically include an HTTP call and a broker publish. Either ordering leaves a crash window.</p>\n      <h2>Idempotency</h2><p>Record message or business idempotency keys in the same transaction as the outcome. The response to a duplicate request is part of the business protocol.</p>\n      <h2>Outbox and saga</h2><p>Commit state and an outbox event together, then publish asynchronously. Consumers remain idempotent. Long workflows use state machines and compensation; compensation is a new business action that can itself fail.</p>\n      <h2>Consensus, order, and recovery</h2><p>Consensus establishes replicated ordering and leadership, not cross-service business transactions. Version events, reject stale updates, keep workflows replayable, and test crashes, duplicates, reordering, and failed compensation.</p>\n      <h2>References</h2><ul><li><a href="https://microservices.io/patterns/data/transactional-outbox.html" target="_blank" rel="noopener noreferrer">Transactional Outbox Pattern</a></li><li><a href="https://microservices.io/patterns/communication-style/idempotent-consumer.html" target="_blank" rel="noopener noreferrer">Idempotent Consumer Pattern</a></li></ul>\n    '}},o=()=>a([{id:1001,order:1,builtInRevision:2,title:"Mesting Music：从 Flutter 原生重构到 Java 服务化后端",excerpt:"从 Vue/Capacitor 到 Flutter 原生客户端，再从 CloudBase 主后端迁移到 Java 21、Spring Boot 4.1 与 MySQL 8：这篇复盘不仅解释播放内核和主题系统，也完整记录数据迁移、认证边界、灰度切换与腾讯云部署。",date:"2026-08-01",category:"Flutter",readTime:28,content:"\n      <blockquote>\n        <p>重构不是把旧页面换一种语言再写一遍，而是保留已经被验证的产品记忆，重新决定什么才应该成为系统的骨架。</p>\n      </blockquote>\n\n      <h2>一、为什么要从 Web 走向 Flutter</h2>\n      <p>Mesting Music 最初只是个人数字空间中的音乐模块。随着完整播放器、歌词、队列、主题、歌单、悬浮歌词和 Android 媒体控制陆续加入，它已经不再是一张网页，而是一款需要持续运行、跨页面保持状态、与系统媒体能力深度协作的音乐产品。</p>\n      <p>Vue 与 Capacitor 版本证明了产品方向，但 WebView 也暴露出边界：复杂主题与视频背景叠加后容易掉帧；页面、音频元素、本地存储和原生桥接之间存在多份状态；后台播放、通知栏、锁屏控制、返回手势和应用生命周期需要不断补丁式适配。于是我决定使用 Flutter 进行独立 Android 原生重构，<mark>不复用旧页面，不用 WebView 包裹界面，只把旧版本当成交互规格和产品经验</mark>。</p>\n\n      <h2>二、先重构产品，再重构代码</h2>\n      <p>动手之前，我先把产品重新整理成六层能力：推荐与发现、完整播放、收藏与音乐档案、主题与播放器装扮、账号与好友共听、服务端与 Android 原生能力。首页也从“展示很多功能”改成四个稳定入口：推荐、发现音乐、我的喜欢、我的。</p>\n      <p>四个页面共享一个常驻的迷你播放器。用户从歌单进入播放器，再进入歌词、队列或好友页面时，声音不会中断，当前歌曲也不会因为 Widget 重建而丢失。这个决定看起来像界面布局，实际上定义了整个应用的状态边界。</p>\n\n      <h3>我坚持的六条设计原则</h3>\n      <ul>\n        <li><strong>音乐优先：</strong>视觉可以有情绪，但不能遮挡播放、搜索和队列操作。</li>\n        <li><strong>单一播放真相：</strong>页面只订阅状态，不各自保存一套“当前歌曲”。</li>\n        <li><strong>队列代表意图：</strong>点击一首歌只播放它；“添加到队列”不应立刻切歌；“播放全部”才建立完整队列。</li>\n        <li><strong>装扮是系统：</strong>主题不只是颜色，还包含背景、明暗模式、播放器形态、角色和动效等级。</li>\n        <li><strong>连接自然发生：</strong>好友、状态与一起听从音乐行为延伸，而不是独立塞进一个社交模块。</li>\n        <li><strong>本地先可靠：</strong>网络、云端或第三方音源失败时，本地收藏、歌单和基础播放仍然可用。</li>\n      </ul>\n\n      <h2>三、播放内核：把声音移出页面生命周期</h2>\n      <p>重构中最重要的不是某个播放器界面，而是建立唯一、持续存在的播放内核。界面通过 Riverpod 读取状态并发出意图，<code>MestingAudioHandler</code> 负责队列、当前媒体项、循环与随机模式，再由 <code>just_audio</code> 执行真正的音频播放。</p>\n\n      <pre><code>Flutter UI\n  → Riverpod Providers\n  → Playback Controller\n  → MestingAudioHandler\n  → just_audio / audio_session\n  → Android Media Service</code></pre>\n\n      <p><code>audio_service</code> 把同一份播放状态连接到后台服务、通知栏、锁屏和耳机按键；<code>audio_session</code> 处理来电、其他音频抢占、拔出耳机与音量策略。这样，无论用户停留在哪个页面，系统看到的歌曲、进度和播放按钮都与应用内部一致。</p>\n\n      <h3>队列与历史为什么必须分开</h3>\n      <p>旧版本里最容易出错的是“上一首”和“下一首”。随机模式下，上一首不能重新随机；队列消费后，也不能再用当前列表猜测用户刚才听过什么。因此新架构把待播队列、当前索引与真实播放历史分开管理：下一首优先消费用户明确加入的队列；上一首回到真实历史；队列为空时才按当前来源和播放模式续播。</p>\n      <p>错误音源也不能让播放器无限跳过。每次失败都有上限和可恢复状态，避免坏链接形成循环。这些规则没有炫目的视觉，却决定了播放器是否值得信任。</p>\n\n      <h2>四、信息架构：让 43 项能力仍然容易理解</h2>\n      <p>最终产品包含 43 项可见能力，但我没有把它们全部摆在首页，而是按用户目标组织：</p>\n      <ul>\n        <li><strong>推荐与发现：</strong>个性推荐、每日推荐、私人混合、时间与状态入口、本地和在线搜索。</li>\n        <li><strong>完整播放：</strong>播放模式、队列、歌词、进度跳转、预取、通知栏与后台连续播放。</li>\n        <li><strong>收藏与音乐档案：</strong>喜欢、个人歌单、最近播放、听歌排行与跨设备恢复。</li>\n        <li><strong>主题与装扮：</strong>25 套静态/动态主题、三种播放器、角色进度条、自定义图片和静音视频背景。</li>\n        <li><strong>账号、好友与一起听：</strong>资料、关注关系、私信、语音消息、状态与同步播放。</li>\n        <li><strong>服务端与原生能力：</strong>账号同步、关系数据、应用内更新、系统分享、返回手势、通知与生命周期恢复。</li>\n      </ul>\n      <p>每个功能都必须回答一个问题：用户此刻是想找到音乐、控制音乐、保存音乐、表达自己，还是和别人建立连接？如果不能回答，它就不应该占据一级入口。</p>\n\n      <h2>五、视觉系统：25 套主题不是 25 张背景图</h2>\n      <p>视觉上保留了经典、蜡笔小新、Hello Kitty、库洛米四组角色语言，并允许用户选择静态场景、动态场景或自定义图片与静音循环视频。主题配置同时决定背景、明暗模式、卡片材质、强调色、启动页、歌单封面、进度角色与动效等级。</p>\n      <p>播放器本身也可以在经典黑胶、流光唱片和星环脉冲之间切换。切换播放器不会中断歌曲，因为播放状态与视觉渲染完全解耦。角色可以沿进度条移动，主题人物可以出现在场景中，但所有装饰都必须避开主要操作区，并在低性能设备上自动降级。</p>\n      <p>设计过程中，我没有把手机界面当作桌面界面的缩小版。手机强调单手操作、底部导航、胶囊播放器和抽屉；更宽的屏幕则允许歌词、队列与完整控制同时出现。<mark>响应式设计不是缩放，而是重新分配注意力</mark>。</p>\n\n      <h2>六、客户端数据：本地优先，但服务边界必须清楚</h2>\n      <p>结构化本地数据使用 Drift 保存。歌曲、收藏、歌单、歌单曲目与在线歌曲快照分别建模，Repository 负责读写，页面不直接操作数据库。在线歌曲加入个人歌单时会保存必要快照，避免下一次启动时因为接口暂时不可用而整首歌消失。</p>\n      <p>主题选择、明暗模式和轻量设置使用 SharedPreferences；账号、跨设备资料、关系链、私信、收藏与播放历史则属于服务端领域。Flutter 仍坚持本地先反馈：网络恢复后再提交或拉取权威状态，而不是让一次收藏操作被网络延迟锁住。</p>\n      <p>路由由 <code>go_router</code> 管理，播放壳层保持常驻。状态由 <code>flutter_riverpod</code> 按领域拆分，页面只监听自己需要的那一小段数据。服务端迁移没有改变这条原则：后端是跨设备数据的权威来源，但不能接管播放内核的实时生命周期。</p>\n\n      <h2>七、为什么从 CloudBase 主后端迁移到 Java 与 MySQL</h2>\n      <p>CloudBase 帮助早期版本快速验证了账号、同步与社交功能，但产品进入长期维护阶段后，我需要更清楚的领域模型、关系约束、版本化数据库迁移和可独立诊断的部署链路。迁移的目标不是为了“换一个更重的技术栈”，而是把数据所有权、认证规则、服务边界和故障位置变得可解释。</p>\n      <p>新的兼容 API 延续了旧版 action 协议，因此 Flutter 不需要一次性重写全部业务调用。客户端通过 <code>AUTH_API_BASE_URL</code> 在旧服务与 Java API 之间切换，让登录、资料、收藏、歌单、好友、私信、播放历史和一起听兼容动作可以逐项验证。</p>\n\n      <pre><code>Flutter Android Client\n  → Nginx /v1/\n  → Java 21 / Spring Boot 4.1\n  → Spring Security / JWT\n  → MySQL 8 / Flyway\n\nSide services\n  → QQ SMTP verification\n  → CVM media storage (test environment)</code></pre>\n\n      <p>Spring Boot 服务实现注册、登录、访问令牌与刷新令牌、验证码找回密码、用户资料、关注与拉黑、私信、收藏、歌单、播放历史、一起听兼容动作和媒体上传。Flyway 让表结构变化进入版本控制，而不是依赖某次人工修改数据库。</p>\n\n      <h2>八、数据迁移：从 19 个集合到可校验的关系模型</h2>\n      <p>迁移前先从 CloudBase 导出 19 个集合，共 676 条原始记录；清洗、去重并映射到关系模型后，向 MySQL 写入 669 行。其中包括 9 个用户、255 条私信和 335 条播放历史。关注关系、歌单、收藏与一起听数据也被保留。</p>\n      <p>“成功导入”不等于迁移完成。我继续检查外键、孤立关注关系、无归属消息和计数差异，最终确认没有孤立的 follow 或 message 记录。CloudBase Auth 的密码散列无法安全迁移，因此没有伪造兼容密码：旧用户需要通过邮箱或手机验证码重置密码；随后又补齐同步了 3 个邮箱与 7 个手机号绑定。</p>\n      <p>这一步最重要的经验是：<mark>迁移报告必须同时写明成功导入了什么，以及什么因为安全边界不能迁移</mark>。否则“数据已迁移”会给用户和维护者一个错误承诺。</p>\n\n      <h2>九、认证、同步与故障边界</h2>\n      <p>认证由 Spring Security 与 JWT 负责，短期访问令牌和刷新令牌分开管理；注册、密码重置和账号恢复使用验证码流程，邮件通过 QQ SMTP 的 SSL 通道发送。接口继续兼容邮箱与手机号两条账号路径，避免迁移后只照顾新用户。</p>\n      <p>收藏、歌单、播放历史和社交关系都拥有明确的服务端记录，但 Flutter 客户端仍保留本地状态与失败反馈。一次请求必须能够区分未认证、校验失败、网络不可达和服务端错误，不能把所有失败都呈现为“加载失败”。这也让排查从“猜客户端还是云函数”变成沿着 Nginx、Spring Boot、SQL 和 SMTP 分层定位。</p>\n\n      <h2>十、部署拓扑与版本状态：测试环境不冒充正式生产</h2>\n      <p>Java 服务部署在腾讯云 Ubuntu 22.04 CVM，通过 systemd 托管，Nginx 只把 <code>/v1/</code> 转发到本机 <code>127.0.0.1:8080</code>。MySQL 仅监听服务器内部，公网只开放 SSH 与 HTTP 所需端口，3306 和 8080 不直接暴露。测试媒体写入 <code>/opt/mesting-api/data/media</code>，元数据 URL 存入 MySQL。</p>\n      <p>当前公开稳定版仍是 <strong>1.0.37（build 38）</strong>；接入 Java + MySQL 的 <strong>1.0.38+39</strong> 是迁移测试版，已经验证登录、注册、密码重置和邮件验证码等主路径。测试环境仍使用公网 IP 与 HTTP，域名和 HTTPS 尚未完成，因此不能把它描述为最终生产部署。CloudBase 在过渡期只保留更新清单与 APK 托管，不再是新的主用户数据后端。</p>\n\n      <h2>十一、性能不是最后补救，而是主题系统的一部分</h2>\n      <p>旧版本的卡顿让我明确了一件事：动效不能只讨论“好不好看”，还要知道何时应该停止。Flutter 版把性能策略放进主题配置：</p>\n      <ul>\n        <li>离开视口的动画、视频背景和高频绘制自动暂停。</li>\n        <li>大图延迟解码并按显示尺寸加载，列表尽量复用组件。</li>\n        <li>完整动效、自动推荐和省电静态三档可切换，低性能设备主动降级。</li>\n        <li>播放进度等高频状态只更新需要它的局部组件。</li>\n        <li>预取下一首但不一次性加载整份媒体库，减少启动压力。</li>\n        <li>应用进入后台后保留声音，暂停不必要的视觉动画与视频。</li>\n      </ul>\n      <p>这也是为什么播放服务与界面必须分开：视觉可以降级、重建或暂停，声音不能因此中断。</p>\n\n      <h2>十二、迁移过程：先搭脊柱，再迁移权威数据</h2>\n      <ol>\n        <li><strong>盘点客户端行为：</strong>记录旧版每个页面真正完成了什么，而不是照着截图复制。</li>\n        <li><strong>定义模型：</strong>先确定 Track、Playlist、Favorite、PlaybackSnapshot、LyricsDocument 和 ThemePreset。</li>\n        <li><strong>重建播放脊柱：</strong>完成本地播放、全局队列、三种模式、后台媒体会话与状态恢复。</li>\n        <li><strong>恢复音乐档案：</strong>接入 Drift、收藏、歌单、歌词与播放历史。</li>\n        <li><strong>重建视觉语言：</strong>把旧 CSS 动效转换为 Flutter 动画和可降级的主题渲染器。</li>\n        <li><strong>建立 Java 兼容 API：</strong>保留既有 action 协议，逐项替换账号、同步、社交与媒体接口。</li>\n        <li><strong>迁移并核对数据：</strong>导出 CloudBase、规范化 MySQL 表、运行 Flyway，并检查外键与记录计数。</li>\n        <li><strong>灰度切换客户端：</strong>通过环境变量连接测试服务，区分稳定版和 Java 后端测试版。</li>\n        <li><strong>真实设备验证：</strong>同时测试播放生命周期、断网、认证过期、密码重置、同步冲突和低性能模式。</li>\n      </ol>\n\n      <h2>十三、使用到的核心技术</h2>\n      <ul>\n        <li><strong>Flutter / Dart：</strong>统一构建 Android 界面、动画与业务模型。</li>\n        <li><strong>Riverpod：</strong>管理播放、歌词、歌单、主题和账号等跨页面状态。</li>\n        <li><strong>go_router：</strong>组织页面路径、深链和常驻播放器壳层。</li>\n        <li><strong>just_audio：</strong>本地文件与在线音源播放、队列、跳转、循环和随机。</li>\n        <li><strong>audio_service：</strong>后台服务、通知栏、锁屏控制与系统媒体会话。</li>\n        <li><strong>audio_session：</strong>音频焦点、来电打断、耳机与其他应用声音协调。</li>\n        <li><strong>Drift / SQLite：</strong>收藏、歌单、曲目关系、播放快照与本地迁移。</li>\n        <li><strong>SharedPreferences：</strong>保存主题和轻量偏好。</li>\n        <li><strong>Java 21 / Spring Boot 4.1：</strong>账号、同步、社交、媒体与兼容 API 的服务端边界。</li>\n        <li><strong>Spring Security / JWT：</strong>登录、访问令牌、刷新令牌与接口鉴权。</li>\n        <li><strong>MySQL 8 / Flyway：</strong>关系数据、约束、索引与可版本化的表结构迁移。</li>\n        <li><strong>Nginx / systemd / 腾讯云 CVM：</strong>反向代理、进程守护与测试环境部署。</li>\n        <li><strong>QQ SMTP：</strong>注册、找回密码与账号恢复所需的邮件验证码。</li>\n        <li><strong>Android 原生能力：</strong>通知、系统分享、返回手势、后台生命周期与应用内更新。</li>\n      </ul>\n\n      <h2>十四、这两次迁移真正改变了什么</h2>\n      <p>第一次迁移改变了客户端的骨架：旧版先有页面，再设法让状态穿过页面；Flutter 版先建立持续存在的播放与本地数据系统，再让不同界面去观察它。第二次迁移改变了数据的权威边界：账号、关系和跨设备状态不再依附于难以审计的云函数组合，而是进入可以版本化、约束和独立部署的 Java 服务。</p>\n      <p>我也更确定了 Mesting Music 的方向：它不是追求“功能最多”的播放器，而是一个能记住听歌习惯、允许表达视觉身份，也能把一首歌自然分享给朋友的个人声音空间。</p>\n      <blockquote>\n        <p>迁移完成的标志，不是技术栈名称全部更新，而是每一份状态都有清楚的归属、可验证的路径和诚实的故障边界。</p>\n      </blockquote>\n    "},{id:1,order:2,title:"Vue3 Composition API 完全指南",excerpt:"深入了解 Vue3 的 Composition API，从 setup 函数、ref、reactive 到 computed、watch，全面掌握响应式编程的核心概念。通过实际案例演示如何组织代码逻辑，提升代码的可维护性和复用性。",date:"2024-01-15",category:"Vue",readTime:10,content:"\n      <h2>什么是 Composition API？</h2>\n      <p>Composition API 是 Vue3 引入的一套新的 API，它提供了一种<mark>更灵活</mark>的方式来组织组件逻辑。与 Options API 相比，Composition API 允许我们更好地组织代码，提高代码的可重用性。</p>\n      \n      <h2>核心概念</h2>\n      <h3>1. ref 和 reactive</h3>\n      <p>ref 和 reactive 是创建响应式数据的两种主要方式。<mark>ref 用于基本类型</mark>，reactive 用于对象类型。</p>\n      \n      <pre><code>import { ref, reactive } from 'vue'\n\n// 使用 ref 创建响应式数据\nconst count = ref(0)\nconst name = ref('Vue')\n\n// 使用 reactive 创建响应式对象\nconst state = reactive({\n  count: 0,\n  name: 'Vue'\n})</code></pre>\n      \n      <h3>2. computed</h3>\n      <p>computed 用于创建计算属性，它会自动追踪依赖，并在依赖变化时重新计算。</p>\n      \n      <pre><code>const doubled = computed(() => count.value * 2)</code></pre>\n      \n      <h3>3. watch 和 watchEffect</h3>\n      <p>watch 用于监听特定数据的变化，watchEffect 会自动追踪其回调函数中使用的所有响应式数据。</p>\n      \n      <pre><code>watch(count, (newValue, oldValue) => {\n  console.log(`count 从 ${oldValue} 变为 ${newValue}`)\n})\n\nwatchEffect(() => {\n  console.log(`count 的值是: ${count.value}`)\n})</code></pre>\n      \n      <h2>优势</h2>\n      <ul>\n        <li>更好的逻辑组织</li>\n        <li>更灵活的代码复用</li>\n        <li>更好的 TypeScript 支持</li>\n        <li>更小的打包体积</li>\n      </ul>\n    "},{id:2,order:3,title:"现代 CSS 技巧与实践",excerpt:"探索 CSS 的最新特性，包括 Flexbox、Grid 布局、CSS 变量、动画和过渡效果。学习如何构建现代化的网页布局，掌握响应式设计的最佳实践，打造美观且高性能的用户界面。",date:"2024-01-10",category:"CSS",readTime:8,content:"\n      <h2>CSS Grid 布局</h2>\n      <p>CSS Grid 是一个<mark>强大的二维布局系统</mark>，可以轻松创建复杂的网页布局。</p>\n      \n      <pre><code>.container {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 20px;\n}</code></pre>\n      \n      <h2>Flexbox 弹性布局</h2>\n      <p>Flexbox 是一维布局系统，非常适合用于创建<mark>灵活的组件布局</mark>。</p>\n      \n      <pre><code>.flex-container {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 10px;\n}</code></pre>\n      \n      <h2>CSS 变量</h2>\n      <p>CSS 变量（自定义属性）允许我们在 CSS 中定义可重用的值，提高代码的可维护性。</p>\n      \n      <pre><code>:root {\n  --primary-color: #3b82f6;\n  --secondary-color: #1e40af;\n  --spacing: 1rem;\n}\n\n.button {\n  background: var(--primary-color);\n  padding: var(--spacing);\n}</code></pre>\n      \n      <h2>现代 CSS 特性</h2>\n      <ul>\n        <li>CSS 自定义属性</li>\n        <li>CSS Grid 和 Flexbox</li>\n        <li>CSS 动画和过渡</li>\n        <li>CSS 滤镜和混合模式</li>\n      </ul>\n    "},{id:3,order:4,title:"JavaScript 异步编程详解",excerpt:"从回调函数到 Promise，再到 Async/Await 语法糖，全面掌握 JavaScript 异步编程的演进历程。深入理解事件循环机制，学会处理复杂的异步场景，编写更优雅的异步代码。",date:"2024-01-05",category:"JavaScript",readTime:12,content:"\n      <h2>异步编程基础</h2>\n      <p>JavaScript 是单线程语言，异步编程是处理耗时操作的关键。</p>\n      \n      <h2>Promise</h2>\n      <p>Promise 是处理异步操作的一种优雅方式，它代表了一个异步操作的最终完成或失败。</p>\n      \n      <h2>Async/Await</h2>\n      <p>Async/Await 是基于 Promise 的语法糖，让异步代码看起来像同步代码一样清晰。</p>\n      \n      <h2>事件循环</h2>\n      <p>理解事件循环机制对于掌握 JavaScript 异步编程至关重要。</p>\n      \n      <h2>最佳实践</h2>\n      <ul>\n        <li>始终处理错误</li>\n        <li>避免回调地狱</li>\n        <li>合理使用 Promise.all</li>\n        <li>理解微任务和宏任务</li>\n      </ul>\n    "},{id:4,order:5,title:"前端性能优化实战",excerpt:"从资源加载优化、代码分割、懒加载到渲染性能优化，全方位提升用户体验。学习使用 Chrome DevTools 进行性能分析，掌握关键性能指标（KPI）的优化策略，让网页飞起来。",date:"2024-01-02",category:"性能优化",readTime:15,content:"\n      <h2>性能优化概述</h2>\n      <p>前端性能优化是提升用户体验的关键，涉及资源加载、渲染、交互等多个方面。</p>\n      \n      <h2>资源加载优化</h2>\n      <ul>\n        <li>代码分割和懒加载</li>\n        <li>图片优化和懒加载</li>\n        <li>使用 CDN 加速资源</li>\n        <li>启用 HTTP/2 和 HTTP/3</li>\n      </ul>\n      \n      <h2>渲染性能优化</h2>\n      <ul>\n        <li>减少 DOM 操作</li>\n        <li>使用虚拟滚动</li>\n        <li>避免强制同步布局</li>\n        <li>合理使用 CSS 动画</li>\n      </ul>\n      \n      <h2>性能分析工具</h2>\n      <p>使用 Chrome DevTools 进行性能分析，关注关键性能指标（KPI）。</p>\n    "},{id:5,order:6,title:"Vite 构建工具深入浅出",excerpt:"了解 Vite 的核心原理，基于 ES Modules 的极速开发服务器和 Rollup 的高效打包。对比传统构建工具的优势，学习插件系统、环境配置和部署优化，大幅提升开发效率和构建速度。",date:"2023-12-28",category:"工具",readTime:10,content:"\n      <h2>Vite 简介</h2>\n      <p>Vite 是新一代前端构建工具，基于 ES Modules 提供极速的开发体验。</p>\n      \n      <h2>核心特性</h2>\n      <ul>\n        <li>极速的冷启动</li>\n        <li>即时的模块热更新</li>\n        <li>基于 Rollup 的高效打包</li>\n        <li>丰富的插件生态</li>\n      </ul>\n      \n      <h2>与传统构建工具对比</h2>\n      <p>Vite 相比 Webpack 等传统工具，在开发体验和构建速度上有显著优势。</p>\n      \n      <h2>最佳实践</h2>\n      <ul>\n        <li>合理配置环境变量</li>\n        <li>使用插件扩展功能</li>\n        <li>优化生产环境构建</li>\n        <li>配置代码分割策略</li>\n      </ul>\n    "},{id:6,order:7,title:"Vue3 学习笔记",excerpt:"记录 Vue3 的学习过程，包括 Composition API、响应式原理、组件通信等核心概念。通过实际案例练习，加深对 Vue3 特性的理解和应用。",date:"2024-01-20",category:"学习记录",readTime:15,content:"\n      <h2>Vue3 核心特性</h2>\n      <p>Vue3 引入了许多新特性，其中最显著的是 Composition API。</p>\n      \n      <h2>Composition API</h2>\n      <p>Composition API 提供了一种更灵活的方式来组织组件逻辑，使代码更易于维护和复用。</p>\n      \n      <h2>响应式原理</h2>\n      <p>Vue3 使用 Proxy 替代了 Vue2 的 Object.defineProperty，提供了更全面的响应式支持。</p>\n    "},{id:7,order:8,title:"CSS Grid 布局练习",excerpt:"通过实际项目练习 CSS Grid 布局，掌握网格布局的核心概念和常用技巧。学习如何创建复杂的网页布局，提高页面的响应式能力。",date:"2024-01-18",category:"学习记录",readTime:10,content:"\n      <h2>CSS Grid 基础</h2>\n      <p>CSS Grid 是一个二维布局系统，可以轻松创建复杂的网页布局。</p>\n      \n      <h2>常用属性</h2>\n      <ul>\n        <li>grid-template-columns</li>\n        <li>grid-template-rows</li>\n        <li>grid-gap</li>\n        <li>grid-area</li>\n      </ul>\n      \n      <h2>实战案例</h2>\n      <p>通过构建一个响应式的作品集页面，练习 CSS Grid 的应用。</p>\n    "}]),a=e=>{const n={1:{title:"Vue 3 Composition API：响应式系统、生命周期与可复用逻辑",excerpt:"以 Vue 3.5+ 为基线，解释 ref、reactive、computed、watch 与 composable 的边界，并用可验证的组件案例说明如何组织状态、清理副作用和控制更新范围。",content:"\n        <p><strong>适用范围：</strong>Vue 3.5+、Composition API、单文件组件。本文讨论稳定 API 与可迁移的工程原则，不把个人偏好当作框架约束。</p>\n        <h2>先定义问题：逻辑应该放在哪里</h2>\n        <p>Composition API 的价值不是把 Options API 的字段换成函数，而是让同一条业务逻辑的状态、派生值、副作用与清理代码保持在同一处。组件应负责组合与展示；可跨组件复用的行为应提取为 composable；领域状态则应由明确的 store 或服务边界持有。</p>\n        <h2>响应式原语的工程边界</h2>\n        <ul><li><code>ref</code> 适合单值状态、DOM 引用和需要整体替换的对象。</li><li><code>reactive</code> 适合结构稳定的对象，但解构时必须使用 <code>toRefs</code> 保留响应式连接。</li><li><code>computed</code> 只表达可缓存的派生值，不承担异步副作用。</li><li><code>watch</code> 用于明确的外部影响，例如请求、存储同步或第三方 API。</li></ul>\n        <h2>副作用、清理与可测试性</h2>\n        <p>监听器和订阅必须拥有对称清理逻辑。请求应配合失效标记或 AbortController，定时器、事件监听和 WebSocket 则在 <code>onUnmounted</code> 中释放。这样组件卸载后不会继续写入已失效状态，也更容易在单元测试中验证。</p>\n        <pre><code>const stop = watch(query, async (value, _, onCleanup) =&gt; {\n  const controller = new AbortController()\n  onCleanup(() =&gt; controller.abort())\n  result.value = await fetchResult(value, controller.signal)\n})</code></pre>\n        <h2>验证清单</h2>\n        <p>检查状态是否有唯一来源、派生值是否可计算、异步结果是否会过期、组件卸载后是否仍有回调，以及更新是否只触发必要的子树。结论是：Composition API 提供组织能力，可靠性来自清晰的状态边界和可测试的副作用管理。</p>\n      "},2:{title:"现代 CSS 布局：从 Grid、Flex 到容器查询与可访问动效",excerpt:"基于现代浏览器标准，梳理 Grid、Flexbox、容器查询、级联层与自定义属性的适用边界，并给出响应式布局和动效降级的验证方法。",content:"\n        <p><strong>适用范围：</strong>现代 Chromium、Firefox 与 Safari。示例遵循 CSS Grid、Flexbox、Container Queries 和 prefers-reduced-motion 的标准语义。</p>\n        <h2>布局决策而不是属性堆叠</h2>\n        <p>Flexbox 解决一维排列与对齐，Grid 解决二维轨道与区域。先确定组件的主轴和内容关系，再选择布局模型；不要用大量绝对定位去模拟本应由轨道表达的结构。</p>\n        <h2>可维护的响应式策略</h2>\n        <p>使用自定义属性集中管理间距、颜色和断点，优先采用 <code>minmax()</code>、<code>clamp()</code> 和 <code>auto-fit</code> 让布局随容器伸缩。容器查询适合组件级响应式：卡片根据自己的宽度变化，而不是依赖页面断点。</p>\n        <pre><code>.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr)); gap: var(--space); }\n.card { container-type: inline-size; }\n@container (min-width: 34rem) { .card { grid-template-columns: 8rem 1fr; } }</code></pre>\n        <h2>级联、动效与可访问性</h2>\n        <p>使用 <code>@layer</code> 明确 reset、组件和工具层的优先级；动效优先使用 transform 与 opacity，并为 <code>prefers-reduced-motion: reduce</code> 提供静态状态。键盘焦点、文字对比度和内容溢出应在布局验收中与视觉一致性同等重要。</p>\n        <h2>验证结论</h2>\n        <p>在窄屏、宽屏、长文本、放大字体和减少动效设置下分别检查布局。现代 CSS 的核心不是更复杂的选择器，而是让内容关系、组件边界和无障碍行为都能从样式结构中读出来。</p>\n      "},3:{title:"JavaScript 异步执行模型：Promise、事件循环与并发控制",excerpt:"从 ECMAScript Promise 语义出发，解释微任务、任务队列、取消与并发限制，帮助你准确判断异步代码的执行顺序和失败传播路径。",content:"\n        <p><strong>适用范围：</strong>浏览器与 Node.js 的标准 Promise API。本文区分语言规范行为与宿主环境调度，不用“异步等于多线程”这种不准确的简化。</p>\n        <h2>事件循环真正决定了什么</h2>\n        <p>JavaScript 代码在当前执行栈清空后，宿主环境才会调度后续工作。Promise 回调进入微任务队列，定时器、网络和用户事件通常进入任务队列；每轮任务结束后会优先清空微任务，因此连续创建微任务也可能延迟渲染。</p>\n        <pre><code>console.log('A')\nPromise.resolve().then(() =&gt; console.log('microtask'))\nsetTimeout(() =&gt; console.log('task'), 0)\nconsole.log('B')\n// A, B, microtask, task</code></pre>\n        <h2>Promise 组合与失败边界</h2>\n        <p><code>Promise.all</code> 用于“全部成功才继续”，<code>allSettled</code> 用于需要完整结果报告的批处理，<code>race</code> 和 <code>any</code> 分别表达首个结算与首个成功。选择组合器时应先写出业务对部分失败的容忍度。</p>\n        <h2>取消、重试与并发上限</h2>\n        <p>Promise 本身不可取消；网络请求应使用 AbortController，重试必须限制次数并使用退避策略。对图片、搜索或批量接口设置并发上限，避免把浏览器连接池、服务端配额和用户带宽同时打满。</p>\n        <h2>验收标准</h2>\n        <p>用时间线记录任务、微任务、渲染和取消事件；测试成功、失败、超时、重复触发与组件卸载。可靠的异步代码不仅“能跑完”，还要能解释顺序、停止过期工作并保留失败信息。</p>\n      "},4:{title:"Web 性能工程：从 Core Web Vitals 到资源与渲染优化",excerpt:"以 LCP、INP、CLS 为可观测指标，建立从网络传输、图片视频、代码拆分到渲染调度的性能诊断流程，避免只凭主观感受优化。",content:"\n        <p><strong>适用范围：</strong>面向真实用户的移动与桌面 Web。指标应结合现场数据、实验室录制和设备能力解释，不能用单次本地分数替代用户体验。</p>\n        <h2>先测量，再决定优化对象</h2>\n        <p>LCP 关注主要内容出现的速度，INP 关注交互响应，CLS 关注布局稳定性。用 Performance 面板、Network 面板和 Web Vitals 采样定位瓶颈，再确认问题来自传输、解码、主线程还是布局。</p>\n        <h2>资源加载策略</h2>\n        <ul><li>首屏关键图片提供尺寸、合适格式和明确优先级。</li><li>非首屏图片使用懒加载，视频提供 poster，并避免移动端默认下载高码率源。</li><li>路由级代码拆分，确保首屏不加载不会立即执行的功能。</li><li>字体、第三方脚本和远程 API 通过预算控制，避免阻塞主要内容。</li></ul>\n        <h2>渲染与交互</h2>\n        <p>减少强制同步布局，优先使用 transform 和 opacity；长列表采用虚拟化或分批渲染；滚动中的动画暂停高成本绘制，组件离开视口后释放观察者和媒体资源。</p>\n        <h2>可复现的验收</h2>\n        <p>固定设备、网络和缓存条件记录基线，分别比较冷启动与回访。优化必须同时验证视觉完整性、键盘操作、低端设备和减少动效设置；只有指标改善且内容没有缺失，才算完成。</p>\n      "},5:{title:"Vite 构建系统：开发服务器、Rollup 与生产发布",excerpt:"从原生 ESM 开发服务器到 Rollup 生产构建，解释 Vite 的依赖预构建、环境变量、代码拆分和静态部署边界，并给出可审计的发布流程。",content:"\n        <p><strong>适用范围：</strong>Vite 6+ 项目。具体配置仍以当前项目安装的 Vite、插件和 Node.js 版本为准，本文不把工具默认行为当作永久 API。</p>\n        <h2>开发与生产是两条不同路径</h2>\n        <p>开发服务器通过原生 ESM 按需提供模块，并用依赖预构建减少重复解析；生产构建则由 Rollup 生成可部署的静态资源。开发环境的快速启动不代表生产包体积或运行时性能已经达标。</p>\n        <h2>配置与边界</h2>\n        <p><code>base</code> 决定子路径部署时的资源前缀，环境变量必须区分公开配置与服务端密钥。插件应只处理明确的转换职责；自定义别名、静态目录和 HTML 注入都应纳入构建产物检查。</p>\n        <pre><code>export default defineConfig(({ mode }) =&gt; ({\n  base: mode === 'production' ? '/project/' : '/',\n  build: { sourcemap: true }\n}))</code></pre>\n        <h2>拆分与发布验证</h2>\n        <p>按路由和重型依赖拆分代码，检查生成的 chunk 是否被首屏意外引入。部署前对 index、深层路由、静态资源 MIME、缓存头和 404 回退进行自动化检查，并保留构建版本与回滚入口。</p>\n        <h2>结论</h2>\n        <p>Vite 的速度来自开发阶段减少不必要的工作；可靠发布则依赖明确的 base、环境、产物和验证流程。两者必须分开测量。</p>\n      "},6:{title:"Vue 3 组件工程：状态边界、通信与可测试性",excerpt:"从单文件组件的职责划分出发，讨论 props、emits、provide/inject、composable 与状态库的边界，建立可维护、可测试的 Vue 3 组件系统。",content:"\n        <p><strong>适用范围：</strong>Vue 3 单文件组件与 TypeScript/JavaScript 混合项目。判断组件质量的标准是职责、依赖和测试边界，而不是文件大小。</p>\n        <h2>组件通信的选择顺序</h2>\n        <ul><li>父子之间使用明确的 props 与 emits，并保持单向数据流。</li><li>深层但局部的依赖可使用 provide/inject，同时定义注入键和默认行为。</li><li>跨页面、跨生命周期的领域状态放入 composable 或状态库。</li><li>不要用全局状态替代一次性的事件通知，也不要让子组件直接修改父状态。</li></ul>\n        <h2>让模板保持可读</h2>\n        <p>把格式化、请求、权限和复杂条件提取为命名清晰的计算值或函数；模板只表达结构。异步加载应暴露 loading、error、empty 和 success 四种状态，避免请求失败时出现不可解释的空白。</p>\n        <h2>可测试的副作用</h2>\n        <p>把网络、时间、存储和路由作为可替换依赖传入 composable。组件测试关注用户可观察的 DOM、事件和状态变化，单元测试关注纯函数与状态转换，不依赖实现细节。</p>\n        <h2>工程结论</h2>\n        <p>可维护组件不是“越小越好”，而是每个状态只拥有一个权威来源，每个副作用都能被停止，每个公开事件都有明确语义。</p>\n      "},7:{title:"CSS Grid 工程实践：轨道、区域与响应式策略",excerpt:"以真实内容约束为起点，系统讲解 Grid 轨道、命名区域、隐式网格、minmax 与 auto-fit，并覆盖长文本、窄屏和组件嵌套的验证要点。",content:"\n        <p><strong>适用范围：</strong>CSS Grid Level 1 的主流实现。示例强调内容适配和可读性，不依赖固定高度或脆弱的像素定位。</p>\n        <h2>先画出内容关系</h2>\n        <p>Grid 容器负责列和行，子项负责放入轨道或命名区域。页面级结构适合使用 <code>grid-template-areas</code>，重复卡片适合使用自动放置与最小轨道宽度。</p>\n        <pre><code>.layout {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) minmax(16rem, 28rem);\n  grid-template-areas: 'main aside';\n  gap: clamp(1rem, 3vw, 3rem);\n}\n@media (max-width: 48rem) { .layout { grid-template-areas: 'main' 'aside'; grid-template-columns: 1fr; } }</code></pre>\n        <h2>避免溢出与隐式陷阱</h2>\n        <p>长文本列通常需要 <code>minmax(0, 1fr)</code>，否则最小内容宽度可能撑破容器。明确是否允许隐式轨道，检查图片尺寸、表格和代码块在窄屏下的最小宽度。</p>\n        <h2>验收矩阵</h2>\n        <p>至少验证 320px 窄屏、平板、宽桌面、放大字体、英文长单词和动态增删卡片。Grid 的成功标准是内容顺序仍然合理、焦点顺序不被视觉布局破坏，且没有依赖固定高度的截断。</p>\n      "},8:{title:"Web 动效工程：Transform、合成层与 reduced-motion",excerpt:"从 transform 的坐标系和 transform-origin 出发，说明如何设计可解释的交互动效、控制合成与布局成本，并为减少动效用户提供等价的静态状态。",content:"\n        <p><strong>适用范围：</strong>CSS Transforms、Transitions、Animations 与 prefers-reduced-motion。动效应解释状态变化，而不是成为内容本身。</p>\n        <h2>选择不会破坏布局的属性</h2>\n        <p>大多数交互优先使用 transform 与 opacity，避免频繁修改会触发布局的 width、top 或 margin。合成层不是越多越好；应通过 Performance 面板确认图层、内存和绘制成本。</p>\n        <pre><code>.card { transition: transform 220ms ease, opacity 220ms ease; }\n.card:hover, .card:focus-within { transform: translateY(-0.35rem); }\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }\n}</code></pre>\n        <h2>距离、时间与起点</h2>\n        <p>小距离、明确的 transform-origin 和与内容层级匹配的缓动通常比夸张位移更可信。进入动效应让用户理解内容出现，退出动效则不应阻止下一步操作。</p>\n        <h2>验证结论</h2>\n        <p>用键盘、触摸、鼠标和减少动效设置分别检查；确认焦点不会因视觉移动丢失，重复进入视口不会叠加动画，低性能设备也能保持可操作。好的动效最终让界面更容易理解，而不是更难使用。</p>\n      "}};return e.map(e=>{const o=t[e.id]||n[e.id],a=r[e.id];return o?{...e,...o,...a,builtInRevision:a?4:o.builtInRevision||2}:e})},i=e((()=>{const e=localStorage.getItem("blog_articles");if(e)try{const n=JSON.parse(e);if(!Array.isArray(n))return o();const t=o(),r=new Set(t.map(e=>String(e.id))),a=new Map(n.map(e=>[String(e.id),e])),i=t.map(e=>{const n=a.get(String(e.id))||{},t=e.builtInRevision&&(n.builtInRevision||0)<e.builtInRevision;return{...e,...t?{}:n,order:e.order}}),s=n.filter(e=>!r.has(String(e.id))),l=[...i,...s].sort((e,n)=>(e.order||e.id||0)-(n.order||n.id||0));return l.length!==n.length&&localStorage.setItem("blog_articles",JSON.stringify(l)),l}catch(n){return o()}return o()})());function s(){return{articles:i,addArticle:e=>{e.id=(i.value.length>0?Math.max(...i.value.map(e=>e.id)):0)+1,e.order=(i.value.length>0?Math.max(...i.value.map(e=>e.order||0)):0)+1,i.value.push(e)},getArticleById:e=>i.value.find(n=>n.id===parseInt(e)),getArticlesByCategory:e=>i.value.filter(n=>n.category===e),updateArticle:(e,n)=>{const t=i.value.findIndex(n=>n.id===e);-1!==t&&(i.value[t]={...i.value[t],...n})},deleteArticle:e=>{const n=i.value.findIndex(n=>n.id===e);if(-1!==n){const e=i.value[n].order||0;i.value.splice(n,1),i.value.forEach(n=>{n.order>e&&(n.order-=1)})}}}}n(i,e=>{try{e.forEach((e,n)=>{e.content});const n=JSON.stringify(e);localStorage.setItem("blog_articles",n);localStorage.getItem("blog_articles")}catch(n){alert("数据保存失败，可能是数据量过大")}},{deep:!0});var l={"全部":"All",Flutter:"Flutter","性能优化":"Performance","工具":"Tooling","学习记录":"Learning Notes"},c={1001:{title:"Mesting Music: From a Native Flutter Rebuild to a Java Service Backend",excerpt:"From Vue and Capacitor to a native Flutter client, then from a CloudBase-primary backend to Java 21, Spring Boot 4.1, and MySQL 8: this retrospective covers playback architecture, data migration, authentication boundaries, staged rollout, and cloud deployment.",content:"\n      <blockquote>\n        <p>A rebuild is not the act of rewriting old screens in a new language. It preserves validated product memory while deciding what should become the new system’s foundation.</p>\n      </blockquote>\n\n      <h2>1. Why Move from the Web to Flutter?</h2>\n      <p>Mesting Music began as a music module inside my personal digital space. As the full player, lyrics, queue, themes, playlists, floating lyrics, and Android media controls grew, it stopped behaving like a page. It became a music product that needed to stay alive, preserve state between screens, and work closely with the operating system.</p>\n      <p>The Vue and Capacitor version validated the product direction, but it also revealed the limits of a WebView-based runtime. Layered themes and video backgrounds could drop frames. Pages, audio elements, browser storage, and native bridges could each hold competing copies of state. Background playback, notifications, lock-screen controls, system back gestures, and lifecycle recovery required increasingly fragile patches.</p>\n      <p>I therefore rebuilt the Android application independently in Flutter. <mark>The old interface was not embedded and its WebView runtime was not reused. It became a behavioral specification and a source of product lessons.</mark></p>\n\n      <h2>2. Rebuild the Product Before Rebuilding the Code</h2>\n      <p>Before implementation, I reorganized the product into six capability layers: discovery, playback, collection, visual identity, social connection, and service/native systems. The main navigation became four stable destinations: For You, Discover Music, Favorites, and Me.</p>\n      <p>Every destination shares one persistent mini player. Moving from a playlist to the full player, lyrics, queue, or a friend’s profile never interrupts the sound or replaces the current track because a widget was rebuilt. This appears to be a layout choice, but it actually defines the state boundary for the entire application.</p>\n\n      <h3>Six Principles Behind the Rebuild</h3>\n      <ul>\n        <li><strong>Music comes first:</strong> visuals may carry emotion, but never obscure playback, search, or queue actions.</li>\n        <li><strong>One playback truth:</strong> screens observe shared state instead of keeping their own “current track.”</li>\n        <li><strong>The queue expresses intent:</strong> tapping a track plays that track; adding to the queue does not switch immediately; Play All is the action that builds a complete queue.</li>\n        <li><strong>Identity is a system:</strong> a theme includes its background, brightness, player form, character, and performance level—not only a color.</li>\n        <li><strong>Connection grows from listening:</strong> friends, statuses, and shared sessions extend music behavior instead of living in an unrelated social module.</li>\n        <li><strong>Local reliability first:</strong> local playback, playlists, and favorites remain useful when cloud services or online sources fail.</li>\n      </ul>\n\n      <h2>3. The Playback Core: Moving Sound Beyond the Widget Lifecycle</h2>\n      <p>The most important part of the rebuild was not a specific player screen. It was a single playback core that remains alive. Flutter widgets use Riverpod to observe state and send user intent. <code>MestingAudioHandler</code> owns the queue, current media item, repeat mode, and shuffle mode, while <code>just_audio</code> performs the actual playback.</p>\n\n      <pre><code>Flutter UI\n  → Riverpod Providers\n  → Playback Controller\n  → MestingAudioHandler\n  → just_audio / audio_session\n  → Android Media Service</code></pre>\n\n      <p><code>audio_service</code> exposes that same state to the background service, notification controls, lock screen, and headset buttons. <code>audio_session</code> coordinates calls, audio focus, unplugged headphones, and interruptions from other apps. Wherever the listener is, the operating system and the application agree about the current track, position, and controls.</p>\n\n      <h3>Why the Queue and History Must Be Separate</h3>\n      <p>Previous and Next are deceptively difficult. In shuffle mode, Previous must not simply randomize again. Once a queued song has played, the application should not reconstruct history by guessing from the visible list. The new architecture therefore separates the pending queue, active source and index, and real playback history.</p>\n      <p>Next consumes explicit queue intent first. Previous follows real history. When the pending queue is empty, playback continues according to the active source and mode. Invalid URLs also have bounded failure handling so a group of broken sources cannot create an infinite skip loop. These rules are visually quiet, but they determine whether the player feels trustworthy.</p>\n\n      <h2>4. Information Architecture for 43 Capabilities</h2>\n      <p>The finished product contains 43 visible capabilities, but the home screen does not expose all of them at once. They are grouped by user goals:</p>\n      <ul>\n        <li><strong>Discovery:</strong> personalized recommendations, Daily Picks, private mixes, time-aware prompts, status-based entry points, and combined local/online search.</li>\n        <li><strong>Playback:</strong> queue management, repeat and shuffle, lyrics, seeking, prefetching, notifications, and continuous background playback.</li>\n        <li><strong>Collection:</strong> favorites, personal playlists, recent plays, listening rankings, and account-based recovery.</li>\n        <li><strong>Visual identity:</strong> 25 static and animated themes, three player styles, character progress indicators, and custom image or muted-video backgrounds.</li>\n        <li><strong>Accounts and shared listening:</strong> profiles, follows, private messages, voice notes, statuses, and synchronized sessions.</li>\n        <li><strong>Services and native systems:</strong> account sync, relational data, in-app updates, system sharing, back gestures, notifications, and lifecycle recovery.</li>\n      </ul>\n      <p>Every feature must answer one question: is the listener trying to find music, control it, save it, express an identity, or connect with someone? If a feature cannot answer that question, it should not occupy a first-level destination.</p>\n\n      <h2>5. The Visual System: More Than 25 Background Images</h2>\n      <p>The visual language retains four character families—Classic, Crayon Shin-chan, Hello Kitty, and Kuromi—alongside static scenes, animated scenes, and custom image or muted looping-video backgrounds. A theme configuration can control the background, brightness mode, card material, accent color, launch screen, playlist artwork, progress character, and animation tier.</p>\n      <p>The full player can also switch between Classic Vinyl, Luminous Vinyl, and Orbital Pulse without interrupting playback because visual rendering and audio state are completely separate. Characters may travel along the progress bar and scenes may move subtly, but decoration avoids the primary control area and can be downgraded on slower devices.</p>\n      <p>Mobile is not a scaled-down desktop. Phones emphasize one-handed interaction, bottom navigation, the capsule player, and sheets. Wider screens can place lyrics, queue, and richer controls together. <mark>Responsive design is the redistribution of attention, not simple scaling.</mark></p>\n\n      <h2>6. Client Data: Local First, with Explicit Service Boundaries</h2>\n      <p>Structured local data is stored with Drift. Tracks, favorites, playlists, playlist-track relationships, and online-track snapshots are modeled separately and accessed through repositories. Screens never write directly to the database. When an online track enters a personal playlist, enough metadata is stored locally to keep it useful during a temporary API outage.</p>\n      <p>Theme selection, brightness mode, and lightweight preferences use SharedPreferences. Accounts, cross-device profiles, social relationships, messages, favorites, and playback history belong to the service domain. Flutter still responds locally first and reconciles authoritative state when connectivity returns instead of blocking a favorite action on network latency.</p>\n      <p><code>go_router</code> organizes navigation while keeping the player shell persistent. <code>flutter_riverpod</code> divides state by domain, and each screen observes only the smallest state fragment it needs. The backend migration did not change that rule: the server is authoritative for cross-device data, but it does not own the real-time playback lifecycle.</p>\n\n      <h2>7. Why Move the Primary Backend from CloudBase to Java and MySQL?</h2>\n      <p>CloudBase helped the early product validate accounts, synchronization, and social features quickly. Long-term maintenance, however, required clearer domain models, relational constraints, versioned schema migrations, and a deployment chain that could be diagnosed independently. The point was not to adopt a heavier stack for its own sake. It was to make data ownership, authentication rules, service boundaries, and failure locations explicit.</p>\n      <p>The new compatibility API preserves the previous action protocol, so Flutter did not need an all-at-once rewrite. <code>AUTH_API_BASE_URL</code> switches the client between the previous service and the Java API while login, profiles, favorites, playlists, follows, messages, history, and Listen Together compatibility actions are verified one by one.</p>\n\n      <pre><code>Flutter Android Client\n  → Nginx /v1/\n  → Java 21 / Spring Boot 4.1\n  → Spring Security / JWT\n  → MySQL 8 / Flyway\n\nSide services\n  → QQ SMTP verification\n  → CVM media storage (test environment)</code></pre>\n\n      <p>The Spring Boot service implements registration, login, access and refresh tokens, verification-code password recovery, user profiles, follows, blocks, private messages, favorites, playlists, playback history, Listen Together compatibility actions, and media uploads. Flyway puts schema changes under version control instead of relying on one-off manual database edits.</p>\n\n      <h2>8. Data Migration: From 19 Collections to a Verifiable Relational Model</h2>\n      <p>The migration exported 19 CloudBase collections containing 676 raw records. After normalization, deduplication, and relational mapping, 669 rows were imported into MySQL. The verified result included 9 users, 255 messages, and 335 playback-history entries, alongside follows, playlists, favorites, and Listen Together data.</p>\n      <p>A successful import is not the end of a migration. Foreign keys, orphaned follows, ownerless messages, and count differences were checked; no orphan follow or message records remained. CloudBase Auth password hashes could not be transferred safely, so no fake compatibility password was created. Existing users must reset their passwords through email or phone verification. Three email bindings and seven phone bindings were synchronized afterward.</p>\n      <p>The central lesson is that <mark>a migration report must state both what moved successfully and what security boundaries made impossible to move</mark>. Otherwise “the data was migrated” becomes a misleading promise.</p>\n\n      <h2>9. Authentication, Synchronization, and Failure Boundaries</h2>\n      <p>Spring Security and JWT now own authentication, with separate access and refresh tokens. Registration, password reset, and account recovery use verification codes delivered through QQ SMTP over SSL. Both email and phone account paths remain supported so the migration does not privilege only new users.</p>\n      <p>Favorites, playlists, playback history, and social relationships have explicit server records, while Flutter retains local state and actionable failure feedback. Requests distinguish unauthenticated, validation, connectivity, and server failures instead of collapsing them into a generic loading error. Diagnosis can now follow the chain through Nginx, Spring Boot, SQL, and SMTP rather than guessing between client code and cloud functions.</p>\n\n      <h2>10. Deployment and Release Status: A Test Environment Is Not Production</h2>\n      <p>The Java service runs on a Tencent Cloud Ubuntu 22.04 CVM under systemd. Nginx forwards only <code>/v1/</code> to <code>127.0.0.1:8080</code>; MySQL remains internal, and ports 3306 and 8080 are not publicly exposed. Test uploads are written to <code>/opt/mesting-api/data/media</code>, with their metadata URLs stored in MySQL.</p>\n      <p>The public stable release remains <strong>1.0.37 (build 38)</strong>. The Java and MySQL connected <strong>1.0.38+39</strong> build is a migration test release whose login, registration, password reset, and email-verification paths have been verified. It still uses a public IP over HTTP; a domain and HTTPS are pending, so it must not be described as a final production deployment. During this transition, CloudBase remains only for the update manifest and APK hosting, not as the new primary user-data backend.</p>\n\n      <h2>11. Performance Is Part of the Theme System</h2>\n      <p>The earlier version taught me that motion cannot be judged only by how it looks. It also needs a clear rule for when it stops. Performance decisions are therefore part of Flutter theme configuration:</p>\n      <ul>\n        <li>Animations, video backgrounds, and frequent painting pause when they leave the viewport.</li>\n        <li>Large images are decoded near their display size and loaded only when needed.</li>\n        <li>Full Motion, Auto, and Battery Saver modes allow graceful visual reduction.</li>\n        <li>High-frequency state such as playback position updates only a small set of widgets.</li>\n        <li>The next track can be prefetched without loading an entire library during startup.</li>\n        <li>Backgrounding the app preserves audio while suspending unnecessary visual work.</li>\n      </ul>\n      <p>This is another reason the player and interface must remain separate: visuals can pause, degrade, or rebuild; the sound must continue.</p>\n\n      <h2>12. The Migration Sequence: Build the Spine, Then Move Authoritative Data</h2>\n      <ol>\n        <li><strong>Inventory client behavior:</strong> document what every old screen actually accomplished instead of copying screenshots.</li>\n        <li><strong>Define domain models:</strong> establish Track, Playlist, Favorite, PlaybackSnapshot, LyricsDocument, and ThemePreset first.</li>\n        <li><strong>Rebuild the playback spine:</strong> local playback, queue rules, three modes, background media sessions, and recovery.</li>\n        <li><strong>Restore the music archive:</strong> Drift, favorites, playlists, lyrics, and listening history.</li>\n        <li><strong>Rebuild the visual language:</strong> translate CSS effects into Flutter animation and a degradable theme renderer.</li>\n        <li><strong>Establish the Java compatibility API:</strong> retain the action protocol while replacing account, sync, social, and media endpoints.</li>\n        <li><strong>Migrate and reconcile data:</strong> export CloudBase, normalize MySQL tables, run Flyway, and verify foreign keys and counts.</li>\n        <li><strong>Switch the client in stages:</strong> connect a test build through configuration and keep stable and Java-backend releases clearly separated.</li>\n        <li><strong>Verify on real devices:</strong> test playback lifecycle, offline states, token expiry, password recovery, sync conflicts, and reduced-performance mode.</li>\n      </ol>\n\n      <h2>13. Core Technology Choices</h2>\n      <ul>\n        <li><strong>Flutter and Dart:</strong> the Android interface, motion system, and domain models.</li>\n        <li><strong>Riverpod:</strong> cross-screen playback, lyrics, playlists, themes, and account state.</li>\n        <li><strong>go_router:</strong> paths, deep navigation, and a persistent player shell.</li>\n        <li><strong>just_audio:</strong> local and online audio, queues, seeking, repeat, and shuffle.</li>\n        <li><strong>audio_service:</strong> background service, notifications, lock-screen controls, and media sessions.</li>\n        <li><strong>audio_session:</strong> focus, call interruption, headset behavior, and audio coexistence.</li>\n        <li><strong>Drift and SQLite:</strong> favorites, playlists, relational track data, snapshots, and migrations.</li>\n        <li><strong>SharedPreferences:</strong> themes and lightweight preferences.</li>\n        <li><strong>Java 21 and Spring Boot 4.1:</strong> service boundaries for accounts, sync, social data, media, and compatibility endpoints.</li>\n        <li><strong>Spring Security and JWT:</strong> login, access tokens, refresh tokens, and endpoint authorization.</li>\n        <li><strong>MySQL 8 and Flyway:</strong> relational data, constraints, indexes, and versioned schema changes.</li>\n        <li><strong>Nginx, systemd, and Tencent Cloud CVM:</strong> reverse proxying, process supervision, and test deployment.</li>\n        <li><strong>QQ SMTP:</strong> verification codes for registration, password recovery, and account restoration.</li>\n        <li><strong>Android platform capabilities:</strong> notifications, system sharing, back gestures, lifecycle handling, and in-app updates.</li>\n      </ul>\n\n      <h2>14. What These Two Migrations Actually Changed</h2>\n      <p>The first migration changed the client’s foundation. The old application began with pages and tried to carry state through them; Flutter begins with persistent playback and local data systems, then lets interfaces observe them. The second migration changed the authority boundary: accounts, relationships, and cross-device state moved from a cloud-function arrangement into a Java service that can be versioned, constrained, and deployed independently.</p>\n      <p>The direction of Mesting Music is now clearer as well. It is not trying to be the player with the longest feature list. It is a personal soundspace that remembers listening behavior, allows visual identity, and makes sharing one song with a friend feel natural.</p>\n      <blockquote>\n        <p>A migration is complete not when every technology label has changed, but when every piece of state has an explicit owner, a verifiable path, and an honest failure boundary.</p>\n      </blockquote>\n    "},1:{title:"The Complete Guide to Vue 3 Composition API",excerpt:"A complete guide to Vue 3’s Composition API, from setup, ref, and reactive to computed and watch. Practical examples show how to organize component logic for clearer, reusable, and maintainable code.",content:"\n      <h2>What Is the Composition API?</h2>\n      <p>The Composition API is a set of APIs introduced in Vue 3. It provides a <mark>more flexible</mark> way to organize component logic. Compared with the Options API, it keeps related logic together and makes code easier to reuse and maintain.</p>\n\n      <h2>Core Concepts</h2>\n      <h3>1. ref and reactive</h3>\n      <p><code>ref</code> and <code>reactive</code> are the two main ways to create reactive state. <mark>Use ref for primitive values</mark> and reactive for objects.</p>\n\n      <pre><code>import { ref, reactive } from 'vue'\n\n// Create reactive primitive values with ref\nconst count = ref(0)\nconst name = ref('Vue')\n\n// Create a reactive object with reactive\nconst state = reactive({\n  count: 0,\n  name: 'Vue'\n})</code></pre>\n\n      <h3>2. computed</h3>\n      <p><code>computed</code> creates derived state. Vue automatically tracks its dependencies and recalculates the value whenever those dependencies change.</p>\n\n      <pre><code>const doubled = computed(() => count.value * 2)</code></pre>\n\n      <h3>3. watch and watchEffect</h3>\n      <p><code>watch</code> observes explicitly selected state, while <code>watchEffect</code> automatically tracks every reactive value used inside its callback.</p>\n\n      <pre><code>watch(count, (newValue, oldValue) => {\n  console.log('count changed from', oldValue, 'to', newValue)\n})\n\nwatchEffect(() => {\n  console.log('current count:', count.value)\n})</code></pre>\n\n      <h2>Benefits</h2>\n      <ul>\n        <li>Clearer organization of related logic</li>\n        <li>More flexible code reuse</li>\n        <li>Stronger TypeScript support</li>\n        <li>Better opportunities for bundle optimization</li>\n      </ul>\n    "},2:{title:"Modern CSS Techniques and Practice",excerpt:"Explore modern CSS features including Flexbox, Grid, custom properties, motion, and transitions. Learn responsive composition practices for interfaces that remain polished, adaptable, and performant.",content:"\n      <h2>CSS Grid Layout</h2>\n      <p>CSS Grid is a <mark>powerful two-dimensional layout system</mark> that makes complex page structures easier to build and maintain.</p>\n\n      <pre><code>.container {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 20px;\n}</code></pre>\n\n      <h2>Flexible Layouts with Flexbox</h2>\n      <p>Flexbox is a one-dimensional layout system designed for <mark>flexible component alignment</mark> along a row or column.</p>\n\n      <pre><code>.flex-container {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 10px;\n}</code></pre>\n\n      <h2>CSS Custom Properties</h2>\n      <p>CSS custom properties let us define reusable design values, making themes and shared interface rules easier to update.</p>\n\n      <pre><code>:root {\n  --primary-color: #3b82f6;\n  --secondary-color: #1e40af;\n  --spacing: 1rem;\n}\n\n.button {\n  background: var(--primary-color);\n  padding: var(--spacing);\n}</code></pre>\n\n      <h2>Modern CSS Features</h2>\n      <ul>\n        <li>Custom properties and design tokens</li>\n        <li>Grid and Flexbox composition</li>\n        <li>Motion, transitions, and transforms</li>\n        <li>Filters and blend modes</li>\n      </ul>\n    "},3:{title:"Asynchronous JavaScript Explained",excerpt:"Follow asynchronous JavaScript from callbacks and Promises to async/await. Understand the event loop, handle complex flows, and write async code that is easier to reason about.",content:"\n      <h2>Asynchronous Programming Fundamentals</h2>\n      <p>JavaScript runs on a single main thread, so asynchronous programming is essential for handling network requests, timers, and other long-running work without blocking the interface.</p>\n\n      <h2>Promise</h2>\n      <p>A Promise represents the eventual completion or failure of an asynchronous operation and provides a structured way to compose its result.</p>\n\n      <h2>Async/Await</h2>\n      <p>Async/await is syntax built on top of Promises. It makes asynchronous flows read more like synchronous code while preserving non-blocking behavior.</p>\n\n      <h2>The Event Loop</h2>\n      <p>Understanding the event loop, task queue, and microtask queue is fundamental to predicting when asynchronous JavaScript will run.</p>\n\n      <h2>Best Practices</h2>\n      <ul>\n        <li>Always handle rejected operations</li>\n        <li>Avoid deeply nested callbacks</li>\n        <li>Use <code>Promise.all</code> when tasks can run together</li>\n        <li>Understand the difference between tasks and microtasks</li>\n      </ul>\n    "},4:{title:"Practical Frontend Performance Optimization",excerpt:"Improve loading, code splitting, lazy loading, and rendering performance across the frontend. Use Chrome DevTools and key metrics to diagnose bottlenecks and build a faster experience.",content:"\n      <h2>Performance in Context</h2>\n      <p>Frontend performance directly shapes the user experience. It includes how quickly resources load, how smoothly the page renders, and how promptly the interface responds.</p>\n\n      <h2>Optimizing Resource Loading</h2>\n      <ul>\n        <li>Split code and load routes on demand</li>\n        <li>Compress images and defer off-screen media</li>\n        <li>Serve static assets through a CDN</li>\n        <li>Use HTTP/2 or HTTP/3 where available</li>\n      </ul>\n\n      <h2>Optimizing Rendering</h2>\n      <ul>\n        <li>Reduce unnecessary DOM work</li>\n        <li>Use virtualization for very long lists</li>\n        <li>Avoid forced synchronous layout</li>\n        <li>Prefer transform and opacity for motion</li>\n      </ul>\n\n      <h2>Performance Analysis</h2>\n      <p>Chrome DevTools can reveal loading, scripting, rendering, and layout bottlenecks. Measure first, then optimize the work that has the greatest effect on the experience.</p>\n    "},5:{title:"A Practical Guide to Vite",excerpt:"Understand Vite’s native ES module development server, Rollup-powered production builds, plugin system, environment configuration, and deployment optimization.",content:"\n      <h2>Introducing Vite</h2>\n      <p>Vite is a modern frontend build tool that uses native ES modules to provide a fast and focused development experience.</p>\n\n      <h2>Core Features</h2>\n      <ul>\n        <li>Near-instant development server startup</li>\n        <li>Fast hot module replacement</li>\n        <li>Efficient production builds powered by Rollup</li>\n        <li>A broad plugin ecosystem</li>\n      </ul>\n\n      <h2>Compared with Traditional Bundlers</h2>\n      <p>Vite serves source modules directly during development, reducing the amount of work required before the browser can display a change.</p>\n\n      <h2>Best Practices</h2>\n      <ul>\n        <li>Separate environment-specific configuration</li>\n        <li>Add plugins only when they provide clear value</li>\n        <li>Inspect and optimize the production bundle</li>\n        <li>Define a deliberate code-splitting strategy</li>\n      </ul>\n    "},6:{title:"Vue 3 Learning Notes",excerpt:"Notes from learning Vue 3, covering the Composition API, reactivity, and component communication through practical exercises and examples.",content:"\n      <h2>Core Features of Vue 3</h2>\n      <p>Vue 3 introduced a range of new capabilities, with the Composition API becoming one of its most visible changes.</p>\n\n      <h2>Composition API</h2>\n      <p>The Composition API offers a flexible way to group related component logic, helping larger components remain easier to understand, reuse, and maintain.</p>\n\n      <h2>How Reactivity Works</h2>\n      <p>Vue 3 uses <code>Proxy</code> instead of Vue 2’s <code>Object.defineProperty</code>, enabling more complete observation of objects and collections.</p>\n    "},7:{title:"Practicing CSS Grid Layouts",excerpt:"Practice the fundamentals and common patterns of CSS Grid through real layouts, including responsive composition and more complex page structures.",content:"\n      <h2>CSS Grid Fundamentals</h2>\n      <p>CSS Grid is a two-dimensional layout system that can express complex page structures with concise, readable rules.</p>\n\n      <h2>Common Properties</h2>\n      <ul>\n        <li><code>grid-template-columns</code></li>\n        <li><code>grid-template-rows</code></li>\n        <li><code>gap</code></li>\n        <li><code>grid-area</code></li>\n      </ul>\n\n      <h2>Practical Exercise</h2>\n      <p>Build a responsive portfolio layout to practice track sizing, named areas, alignment, and breakpoint-driven changes.</p>\n    "},8:{title:"Interactive Motion Design",excerpt:"A practical introduction to CSS transforms: coordinate systems, translation, rotation, scaling, skewing, and motion that responds without disturbing the surrounding layout.",content:"\n      <h2>Transforms: The Foundation of Interactive Motion</h2>\n      <p>CSS <code>transform</code> is the core property for moving an element in two or three dimensions. It can translate, rotate, scale, and skew an element without changing the document flow around it.</p>\n      <p>That separation makes transforms especially useful for interaction. A card can react to a pointer, a button can acknowledge a click, and an illustration can gain depth while the rest of the interface remains stable.</p>\n\n      <h2>Coordinate Systems: x, y, and z</h2>\n      <p>Every movement needs a coordinate system. In browser space, the horizontal <code>x</code> axis increases to the right and decreases to the left. The vertical <code>y</code> axis increases downward and decreases upward.</p>\n\n      <h3>2D coordinates</h3>\n      <ul>\n        <li><code>x</code>: right is positive; left is negative</li>\n        <li><code>y</code>: down is positive; up is negative</li>\n      </ul>\n\n      <h3>3D coordinates</h3>\n      <p>When perspective is involved, the <code>z</code> axis adds depth. Positive values move an element closer to the viewer, while negative values move it farther away.</p>\n\n      <h2>Core Transform Functions</h2>\n      <ul>\n        <li><code>translate(x, y)</code> moves an element along the two-dimensional plane.</li>\n        <li><code>translate3d(x, y, z)</code> adds depth and can help create layered motion.</li>\n        <li><code>rotate()</code> turns an element around its origin.</li>\n        <li><code>scale()</code> changes visual size without recalculating layout.</li>\n        <li><code>skew()</code> shears an element to introduce directional energy.</li>\n      </ul>\n\n      <pre><code>.project-card:hover {\n  transform: translateY(-8px) rotate(-1deg) scale(1.015);\n}</code></pre>\n\n      <h2>Transform Origin Changes the Feeling</h2>\n      <p><code>transform-origin</code> defines the point around which rotation and scaling happen. A centered origin feels balanced; an origin near an edge can make an element feel hinged, lifted, or pulled into view.</p>\n\n      <pre><code>.cover {\n  transform-origin: 20% 80%;\n  transform: rotate(-4deg);\n}</code></pre>\n\n      <h2>Motion Should Clarify an Interaction</h2>\n      <p>Motion works best when it explains cause and effect: an item rises because it is selectable, a panel expands because it contains more detail, and a state change settles because the action is complete.</p>\n      <p>Keep the distance small, the duration intentional, and the easing natural. Prefer <code>transform</code> and <code>opacity</code> for most interface animation so the experience remains fluid even when the page is busy.</p>\n    "}},d=(e,n)=>{if(!e||n)return e;const t=c[e.id]||{},r=Object.prototype.hasOwnProperty.call(c,e.id),o=!0===e.translationOverride,a=n=>{const a=e[`${n}En`],i=t[n];return o?a||i||e[n]:r?i||a||e[n]:a||i||e[n]};return{...e,title:a("title"),excerpt:a("excerpt"),content:a("content"),category:e.categoryEn||l[e.category]||e.category,readTime:e.readTimeEn||e.readTime}};export{d as n,s as r,l as t};